/* DAWAH X — ahmad, অধ্যায় 53 · খণ্ড 53 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][53]=[[10401,10401,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَسْتَخْلِفُهُ عَلَى الصَّلَاةِ ‏ ‏إِذَا حَجَّ أَوْ اعْتَمَرَ فَيُصَلِّي بِالنَّاسِ فَيُكَبِّرُ خَلْفَ الرُّكُوعِ وَخَلْفَ السُّجُودِ فَإِذَا انْصَرَفَ قَالَ إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10402,10402,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوا لَا إِلَهَ إِلَّا اللَّهُ فَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏ ‏هَكَذَا وَجَدْتُ فِي أَصْلِ ذَلِكَ ‏","","",""],[10403,10403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[10404,10404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَرْوَاحُ جُنُودٌ مُجَنَّدَةٌ فَمَا تَعَارَفَ مِنْهَا ائْتَلَفَ وَمَا تَنَاكَرَ مِنْهَا اخْتَلَفَ ‏","","",""],[10405,10405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَلَسَ قَوْمٌ مَجْلِسًا فَتَفَرَّقُوا عَنْ غَيْرِ ذِكْرِ اللَّهِ إِلَّا تَفَرَّقُوا عَنْ مِثْلِ ‏ ‏جِيفَةِ ‏ ‏حِمَارٍ وَكَانَ ذَلِكَ الْمَجْلِسُ حَسْرَةً عَلَيْهِمْ يَوْمَ الْقِيَامَةِ ‏","","",""],[10406,10406,"","","‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اطَّلَعَ فِي دَارِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَفُقِئَتْ عَيْنُهُ هُدِرَتْ ‏","","",""],[10407,10407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَتَتَّبِعُنَّ سَنَنَ مَنْ قَبْلَكُمْ الشِّبْرَ بِالشِّبْرِ وَالذِّرَاعَ بِالذِّرَاعِ وَالْبَاعَ بِالْبَاعِ حَتَّى لَوْ أَنَّ أَحَدَهُمْ دَخَلَ جُحْرَ ضَبٍّ لَدَخَلْتُمُوهُ قَالُوا يَا رَسُولَ اللَّهِ أَمِنَ ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏قَالَ مَنْ إِذًا ‏","","",""],[10408,10408,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ ثَلَاثُونَ كَذَّابًا ‏","","",""],[10409,10409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَالْيَدَانِ تَزْنِيَانِ وَالرِّجْلَانِ تَزْنِيَانِ وَيُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ الْفَرْجُ ‏","","",""],[10410,10410,"","","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى أَبُو بِشْرٍ الرَّاسِبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي وَصَعِدَتْ قَدَمَيَّ ‏ ‏وَفِي نُسْخَةٍ وَضَعْتُ قَدَمَيَّ ‏ ‏حَيْثُ تُوضَعُ أَقْدَامُ الْأَنْبِيَاءِ مِنْ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَعُرِضَ عَلَيَّ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏قَالَ فَإِذَا أَقْرَبُ النَّاسِ بِهِ شَبَهًا ‏ ‏عُرْوَةُ بْنُ مَسْعُودٍ ‏ ‏وَعُرِضَ عَلَيَّ ‏ ‏مُوسَى ‏ ‏فَإِذَا رَجُلٌ ضَرْبٌ مِنْ الرِّجَالِ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوأَةَ ‏ ‏وَعُرِضَ عَلَيَّ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ فَإِذَا أَقْرَبُ النَّاسِ شَبَهًا بِصَاحِبِكُمْ ‏","","",""],[10411,10411,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏بَابُ بْنُ عُمَيْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتْبَعُ الْجِنَازَةَ صَوْتٌ وَلَا نَارٌ وَلَا ‏ ‏يُمْشَى بَيْنَ يَدَيْهَا ‏","","",""],[10412,10412,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ حَتَّى تَحْتَرِقَ ثِيَابُهُ وَتَخْلُصَ إِلَيْهِ خَيْرٌ لَهُ مِنْ أَنْ ‏ ‏يَطَأَ ‏ ‏عَلَى قَبْرٍ ‏","","",""],[10413,10413,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا دَامَ يَنْتَظِرُ الصَّلَاةَ تَقُولُ الْمَلَائِكَةُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ يَنْصَرِفْ أَوْ ‏ ‏يُحْدِثْ ‏ ‏فَقِيلَ لَهُ مَا ‏ ‏يُحْدِثُ ‏ ‏قَالَ ‏ ‏يَفْسُو أَوْ يَضْرِطُ ‏","","",""],[10414,10414,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِرَاءٌ ‏ ‏فِي الْقُرْآنِ كُفْرٌ ‏","","",""],[10415,10415,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُمْنَعْنَ إِمَاءُ اللَّهِ مَسَاجِدَ اللَّهِ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[10416,10416,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا مِنْ مَنَاقِبِ الْخَيْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ إِنَّكُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ثُمَّ مُرَّ عَلَيْهِ بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا شَرًّا مِنْ مَنَاقِبِ الشَّرِّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ‏","","",""],[10417,10417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْبَرِي عَلَى حَوْضِي وَإِنَّ مَا بَيْنَ مِنْبَرِي وَبَيْتِي لَرَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَصَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏كَأَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[10418,10418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا انْقَطَعَ ‏ ‏شِسْعُ ‏ ‏أَحَدِكُمْ فَلَا يَمْشِي فِي نَعْلٍ حَتَّى يُصْلِحَهَا ‏","","",""],[10419,10419,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ { ‏عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا ‏} ‏قَالَ ‏ ‏هُوَ الْمَقَامُ الَّذِي أَشْفَعُ لِأُمَّتِي فِيهِ ‏","","",""],[10420,10420,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ وَحِسَابُهُمْ عَلَى اللَّهِ ‏ ‏قَالَ ‏ ‏فَلَمَّا قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَارْتَدَّ مَنْ ارْتَدَّ أَرَادَ ‏ ‏أَبُو بَكْرٍ ‏ ‏قِتَالَهُمْ قَالَ ‏ ‏عُمَرُ ‏ ‏كَيْفَ تُقَاتِلُ هَؤُلَاءِ الْقَوْمِ وَهُمْ ‏ ‏يُصَلُّونَ قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَاللَّهِ لَأُقَاتِلَنَّ قَوْمًا ارْتَدُّوا عَنْ الزَّكَاةِ وَاللَّهِ لَوْ مَنَعُونِي عَنَاقًا مِمَّا فَرَضَ اللَّهُ وَرَسُولُهُ لَقَاتَلْتُهُمْ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏فَلَمَّا رَأَيْتُ اللَّهَ شَرَحَ صَدْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏لِقِتَالِهِمْ عَرَفْتُ أَنَّهُ الْحَقُّ ‏","","",""],[10421,10421,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏وَخِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ ثُمَّ يَتَوَضَّأُ مِنْهُ ‏","","",""],[10422,10422,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏أَنَّهُ بَيْنَا هُوَ جَالِسٌ مَعَ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏إِذْ مَرَّ بِهِمْ ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏خَتَنُ ‏ ‏زَيْدِ بْنِ زِيَادٍ الْجُهَنِيِّ ‏ ‏فَدَعَاهُ ‏ ‏نَافِعٌ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ مَعَ الْإِمَامِ أَفْضَلُ مِنْ خَمْسٍ وَعِشْرِينَ صَلَاةً يُصَلِّيهَا وَحْدَهُ ‏","","",""],[10423,10423,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ بِقِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَ فِيهِ ‏ ‏بِعَزِيمَةٍ ‏ ‏وَكَانَ يَقُولُ مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[10424,10424,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[10425,10425,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏","","",""],[10426,10426,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعَتَيْنِ وَعَنْ لِبْسَتَيْنِ وَعَنْ صَلَاتَيْنِ وَعَنْ صِيَامِ يَوْمَيْنِ وَعَنْ ‏ ‏الْمُلَامَسَةِ ‏ ‏وَالْمُنَابَذَةِ ‏ ‏وَاشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَعَنْ ‏ ‏الِاحْتِبَاءِ ‏ ‏فِي ثَوْبٍ وَاحِدٍ كَاشِفًا عَنْ فَرْجِهِ وَعَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَعَنْ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَعَنْ صِيَامِ يَوْمِ الْفِطْرِ ‏","","",""],[10427,10427,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فَلَا تَأْتُوهَا وَأَنْتُمْ ‏ ‏تَسْعَوْنَ ‏ ‏وَأْتُوهَا وَعَلَيْكُمْ السَّكِينَةُ فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا فَإِنَّ أَحَدَكُمْ فِي صَلَاةٍ مَا كَانَ يَعْمِدُ إِلَى الصَّلَاةِ ‏","","",""],[10428,10428,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَمْرٍو ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْمُطَّلِبَ بْنَ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ الْمَخْزُومِيَّ ‏ ‏يَقُولُ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَتَوَضَّأُ مِنْ طَعَامٍ أَجِدُهُ حَلَالًا فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ لِأَنَّ النَّارَ مَسَّتْهُ قَالَ فَجَمَعَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَصًا بَيْنَ يَدَيْهِ فَقَالَ أَشْهَدُ عَدَدَ هَذَا الْحَصَى لَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[10429,10429,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَسْتَامُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبْ عَلَى خِطْبَةِ أَخِيهِ ‏","","",""],[10430,10430,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ ‏ ‏وَسُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَخْطُبْ الرَّجُلُ عَلَى خِطْبَةِ أَخِيهِ وَلَا ‏ ‏يَسْتَمْ ‏ ‏عَلَى ‏ ‏سِيمَةِ ‏ ‏أَخِيهِ ‏","","",""],[10431,10431,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[10432,10432,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَى ‏ ‏النَّجَاشِيَّ ‏ ‏لِأَصْحَابِهِ ثُمَّ قَالَ اسْتَغْفِرُوا لَهُ ثُمَّ خَرَجَ بِأَصْحَابِهِ إِلَى الْمُصَلَّى فَقَامَ فَصَلَّى بِهِمْ كَمَا ‏ ‏يُصَلِّي عَلَى الْجَنَائِزِ ‏","","",""],[10433,10433,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏وُهَيْبٌ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُتِحَ مِنْ رَدْمِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏مِثْلُ ذَلِكَ وَحَلَّقَ تِسْعِينَ وَضَمَّهَا ‏","","",""],[10434,10434,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا يَسُرُّنِي أَنَّ ‏ ‏أُحُدًا ‏ ‏ذَاكُمْ ذَهَبًا عِنْدِي يَأْتِي عَلَيْهِ ثَلَاثَةُ أَيَّامٍ وَعِنْدِي مِنْهُ دِينَارٌ إِلَّا شَيْئًا ‏ ‏أَرْصُدُهُ ‏ ‏فِي دَيْنٍ عَلَيَّ ‏","","",""],[10435,10435,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ كَنْزُ أَحَدِكُمْ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ يَفِرُّ مِنْهُ صَاحِبُهُ وَهُوَ يَطْلُبُهُ حَتَّى يُلْقِمَهُ أَصَابِعَهُ ‏","","",""],[10436,10436,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقِيمُ لَكَ الْمَرْأَةُ عَلَى خَلِيقَةٍ وَاحِدَةٍ وَإِنَّمَا هِيَ كَالضِّلَعِ إِنْ تُقِمْهَا تَكْسِرْهَا وَإِنْ تَتْرُكْهَا تَسْتَمْتِعْ بِهَا وَفِيهَا عِوَجٌ ‏","","",""],[10437,10437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا ‏ ‏الْيَهُودَ ‏ ‏حَتَّى يَخْتَبِئَ الْيَهُودِيُّ وَرَاءَ الْحَجَرِ فَيَقُولُ الْحَجَرُ يَا مُسْلِمُ هَذَا يَهُودِيٌّ يَخْتَبِئُ وَرَائِي تَعَالَ فَاقْتُلْهُ ‏","","",""],[10438,10438,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَتَطَاوَلَ النَّاسُ بِالْبُنْيَانِ ‏","","",""],[10439,10439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَإِذَا طَلَعَتْ وَرَآهَا النَّاسُ آمَنُوا أَجْمَعُونَ فَذَاكَ حِينَ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[10440,10440,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمْ الشَّعْرُ ‏","","",""],[10441,10441,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا ‏ ‏التُّرْكَ ‏ ‏صِغَارَ الْعُيُونِ حُمْرَ الْوُجُوهِ ‏ ‏ذُلْفَ ‏ ‏الْأُنُوفِ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ ‏ ‏الْمُطْرَقَةُ ‏","","",""],[10442,10442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يَفِيضَ ‏ ‏فِيكُمْ الْمَالُ وَحَتَّى يُهِمَّ الرَّجُلَ بِمَالِهِ مَنْ يَقْبَلُهُ مِنْهُ حِينَ يَتَصَدَّقُ بِهِ فَيَقُولُ الَّذِي يُعْرَضُ عَلَيْهِ لَا أَرَبَ لِي بِهِ ‏","","",""],[10443,10443,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يُقْبَضَ ‏ ‏الْعِلْمُ وَيَتَقَارَبَ الزَّمَانُ وَتَكْثُرَ الزَّلَازِلُ وَتَظْهَرَ الْفِتَنُ وَيَكْثُرَ ‏ ‏الْهَرْجُ ‏ ‏قَالَ ‏ ‏الْهَرْجُ ‏ ‏أَيُّمَا هُوَ يَا رَسُولَ اللَّهِ قَالَ الْقَتْلُ الْقَتْلُ ‏","","",""],[10444,10444,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَقْتَتِلَ فِئَتَانِ عَظِيمَتَانِ تَكُونُ بَيْنَهُمَا مَقْتَلَةٌ عَظِيمَةٌ وَدَعْوَاهُمَا وَاحِدَةٌ ‏","","",""],[10445,10445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَنْبَعِثَ دَجَّالُونَ كَذَّابُونَ قَرِيبٌ مِنْ ثَلَاثِينَ كُلُّهُمْ يَزْعُمُ أَنَّهُ رَسُولُ اللَّهِ ‏","","",""],[10446,10446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَمُرَّ الرَّجُلُ بِقَبْرِ الرَّجُلِ فَيَقُولَ يَا لَيْتَنِي مَكَانَهُ مَا بِهِ حُبُّ لِقَاءِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[10447,10447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ ‏ ‏لِيَعْزِمْ ‏ ‏الْمَسْأَلَةَ فَإِنَّهُ لَا مُكْرِهَ لَهُ ‏","","",""],[10448,10448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏","","",""],[10449,10449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا رَجُلٌ ‏ ‏يَتَبَخْتَرُ ‏ ‏فِي بُرْدَيْهِ قَدْ أَعْجَبَتْهُ نَفْسُهُ إِذْ خَسَفَ اللَّهُ بِهِ الْأَرْضَ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِي بَطْنِهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[10450,10450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُكْلَمُ ‏ ‏عَبْدٌ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ جُرْحُهُ يَوْمَ الْقِيَامَةِ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏","","",""],[10451,10451,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ الْمَدَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعٌ لَا يَدَعُهَا النَّاسُ مِنْ أَمْرِ الْجَاهِلِيَّةِ ‏ ‏النِّيَاحَةُ ‏ ‏وَالتَّعَايُرُ فِي الْأَحْسَابِ وَقَوْلُهُمْ سُقِينَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَالْعَدْوَى جَرِبَ بَعِيرٌ فَأَجْرَبَ مِائَةَ بَعِيرٍ فَمَنْ أَجْرَبَ الْأَوَّلَ ‏","","",""],[10452,10452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَشَاهِدٌ يَوْمَ مَاتَ ‏ ‏الْحَسَنُ ‏ ‏فَذَكَرَ الْقِصَّةَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَحَبَّهُمَا فَقَدْ أَحَبَّنِي وَمَنْ أَبْغَضَهُمَا فَقَدْ أَبْغَضَنِي ‏","","",""],[10453,10453,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي مَمْلُوكٍ عُتِقَ مِنْ مَالِهِ إِنْ كَانَ لَهُ مَالٌ ‏","","",""],[10454,10454,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةُ ‏","","",""],[10455,10455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمٍ الْجَيْشَانِيِّ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏عَبْدُ اللَّهِ بْنُ هُرْمُزَ ‏ ‏مَوْلًى مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَبِعَ جِنَازَةً فَحَمَلَ مِنْ عُلُوِّهَا وَحَثَا فِي قَبْرِهَا وَقَعَدَ حَتَّى يُؤْذَنَ لَهُ آبَ ‏ ‏بِقِيرَاطَيْنِ ‏ ‏مِنْ الْأَجْرِ كُلُّ ‏ ‏قِيرَاطٍ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[10456,10456,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ الشَّيْطَانُ الْمُنَادِيَ يُنَادِي بِالصَّلَاةِ خَرَجَ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الصَّوْتَ فَإِذَا فَرَغَ رَجَعَ فَوَسْوَسَ فَإِذَا أَخَذَ فِي الْإِقَامَةِ فَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[10457,10457,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَثْقَلَ الصَّلَاةِ عَلَى الْمُنَافِقِينَ صَلَاةُ الْعِشَاءِ الْآخِرَةِ وَصَلَاةُ الْفَجْرِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏ ‏وَلَوْ عَلِمَ أَحَدُكُمْ أَنَّهُ إِذَا وَجَدَ عَرْقًا مِنْ شَاةٍ سَمِينَةٍ أَوْ مِرْمَاتَيْنِ حَسَنَتَيْنِ لَأَتَيْتُمُوهَا أَجْمَعِينَ لَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلَاةِ فَتُقَامَ ثُمَّ آمُرَ رَجُلًا ‏ ‏يُصَلِّي بِالنَّاسِ ثُمَّ آخُذَ حُزَمًا مِنْ حَطَبٍ فَآتِيَ الَّذِينَ تَخَلَّفُوا عَنْ الصَّلَاةِ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏وَهَذَا أَتَمُّ ‏","","",""],[10458,10458,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ يَعْنِي ابْنَ غَالِبٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ ‏ ‏الْإِيمَانُ بِاللَّهِ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ فَإِنْ لَمْ أَسْتَطِعْ ذَلِكَ قَالَ احْبِسْ نَفْسَكَ عَنْ الشَّرِّ فَإِنَّهَا صَدَقَةٌ تَصَدَّقُ بِهَا عَلَى نَفْسِكَ ‏","","",""],[10459,10459,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ عَبَّادٍ السَّدُوسِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ يُقْرَأَ ‏ ‏بِالسَّمَوَاتِ ‏ ‏فِي الْعِشَاءِ ‏","","",""],[10460,10460,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏بَابُ بْنُ عُمَيْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُتْبَعُ الْجِنَازَةُ بِصَوْتٍ وَلَا ‏ ‏يُمْشَى بَيْنَ يَدَيْهَا بِنَارٍ ‏","","",""],[10461,10461,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ الْمُسْلِمُ فِي صَلَاةٍ مَا دَامَ فِي مُصَلَّاهُ قَاعِدًا وَلَا يَحْبِسُهُ إِلَّا انْتِظَارُ الصَّلَاةِ وَالْمَلَائِكَةُ يَقُولُونَ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏","","",""],[10462,10462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏الضَّحَّاكُ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ مَا صَلَّيْتُ وَرَاءَ أَحَدٍ أَشْبَهَ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فُلَانٍ إِنْسَانًا ‏ ‏قَدْ سَمَّاهُ ‏ ‏قَالَ ‏ ‏الضَّحَّاكُ ‏ ‏فَحَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَّيْتُ وَرَاءَ ذَلِكَ الرَّجُلِ فَرَأَيْتُهُ ‏ ‏يُطَوِّلُ الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَيُخِفُّ الْآخِرَيْنِ وَخَفَّفَ الْعَصْرَ وَيَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَيَقْرَأُ فِي الْعِشَاءِ ‏ ‏بِالشَّمْسِ وَضُحَاهَا ‏ ‏وَمَا يُشْبِهُهَا ثُمَّ يَقْرَأُ فِي الصُّبْحِ بِالطُّوَالِ مِنْ ‏ ‏الْمُفَصَّلِ ‏","","",""],[10463,10463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غَدْوَةٌ ‏ ‏فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏رَوْحَةٌ ‏ ‏خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[10464,10464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[10465,10465,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ يَعْنِي الْفِرْيَابِيَّ ‏ ‏بِمَكَّةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏قُرَّةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَذْفُ ‏ ‏السَّلَامِ سُنَّةٌ ‏","","",""],[10466,10466,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْمَعْ الرَّجُلُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا بَيْنَهَا وَبَيْنَ خَالَتِهَا ‏","","",""],[10467,10467,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ يَعْنِي ابْنَ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجْدَتَيْ السَّهْوِ بَعْدَ السَّلَامِ ‏","","",""],[10468,10468,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وَابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ وَالْإِمَامُ يَخْطُبُ يَوْمَ الْجُمُعَةِ أَنْصِتْ فَقَدْ لَغَوْتَ ‏","","",""],[10469,10469,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَوْدُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي حَدْرَدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَزَقَ فِي الْمَسْجِدِ فَلْيَحْفِرْ فَلْيُبْعِدْ وَإِلَّا بَزَقَ فِي ثَوْبِهِ ‏","","",""],[10470,10470,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏مُؤَذِّنِ ‏ ‏دِمَشْقَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ لُدَيْنٍ الْأَشْعَرِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ صَوْمِ الْجُمُعَةِ ‏ ‏فَقَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمُ الْجُمُعَةِ يَوْمُ عِيدٍ فَلَا تَجْعَلُوا يَوْمَ عِيدِكُمْ يَوْمَ صِيَامٍ إِلَّا أَنْ تَصُومُوا قَبْلَهُ أَوْ بَعْدَهُ ‏","","",""],[10471,10471,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ الْخَيَّاطُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى سُوقِ ‏ ‏بَنِي قَيْنُقَاعَ ‏ ‏مُتَّكِئًا عَلَى يَدِي فَطَافَ فِيهَا ثُمَّ رَجَعَ ‏ ‏فَاحْتَبَى ‏ ‏فِي الْمَسْجِدِ وَقَالَ أَيْنَ ‏ ‏لَكَاعٌ ‏ ‏ادْعُوا لِي ‏ ‏لَكَاعًا ‏ ‏فَجَاءَ ‏ ‏الْحَسَنُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَاشْتَدَّ حَتَّى ‏ ‏وَثَبَ ‏ ‏فِي ‏ ‏حَبْوَتِهِ ‏ ‏فَأَدْخَلَ فَمَهُ فِي فَمِهِ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أُحِبُّهُ فَأَحِبَّهُ وَأَحِبَّ مَنْ يُحِبُّهُ ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا رَأَيْتُ ‏ ‏الْحَسَنَ ‏ ‏إِلَّا فَاضَتْ عَيْنِي ‏ ‏أَوْ دَمَعَتْ عَيْنِي أَوْ بَكَتْ شَكَّ ‏ ‏الْخَيَّاطُ ‏","","",""],[10472,10472,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ ثُمَّ يُتَوَضَّأَ مِنْهُ ‏","","",""],[10473,10473,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعْتُمْ الْإِقَامَةَ فَامْشُوا وَلَا تُسْرِعُوا وَعَلَيْكُمْ السَّكِينَةَ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَاقْضُوا ‏ ‏وَقَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فَأَتِمُّوا فَأْتُوا وَعَلَيْكُمْ السَّكِينَةَ ‏","","",""],[10474,10474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ فَجَاءَ مَعَ الرَّسُولِ فَذَاكَ لَهُ إِذْنٌ ‏","","",""],[10475,10475,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ وَمَا يَرَى أَنَّهَا تَبْلُغُ حَيْثُ بَلَغَتْ ‏ ‏يَهْوِي بِهَا فِي النَّارِ سَبْعِينَ خَرِيفًا ‏","","",""],[10476,10476,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَيْنَمَا ‏ ‏رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ فَأَخَذَهُ فَشَكَرَ اللَّهُ عَزَّ وَجَلَّ لَهُ فَغَفَرَ لَهُ ‏","","",""],[10477,10477,"","","‏ ‏و قَالَ ‏ ‏الشُّهَدَاءُ خَمْسَةٌ ‏ ‏الْمَطْعُونُ ‏ ‏وَالْمَبْطُونُ ‏ ‏وَالْغَرِقُ وَصَاحِبُ الْهَدْمِ وَالشَّهِيدُ فِي سَبِيلِ اللَّهِ ‏","","",""],[10478,10478,"","","‏ ‏و قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا لَهُمْ فِي النِّدَاءِ وَالصَّفِّ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ ‏ ‏لَاسْتَهَمُوا ‏ ‏وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ عَلِمُوا مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏","","",""],[10479,10479,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏","","",""],[10480,10480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ وَمَا يَرَى أَنَّهَا تَبْلُغُ حَيْثُ بَلَغَتْ يَهْوِي بِهَا فِي النَّارِ سَبْعِينَ خَرِيفًا ‏","","",""],[10481,10481,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْعَبْدَ الْمُؤْمِنَ مَا دَامَ فِي مُصَلَّاهُ لَا يَحْبِسُهُ إِلَّا انْتِظَارُ الصَّلَاةِ وَالْمَلَائِكَةُ مَعَهُ تَقُولُ اللَّهُمَّ ارْحَمْهُ اللَّهُمَّ اغْفِرْ لَهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏","","",""],[10482,10482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غَدْوَةٌ ‏ ‏فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏رَوْحَةٌ ‏ ‏خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا أَوْ الدُّنْيَا وَمَا عَلَيْهَا ‏","","",""],[10483,10483,"","","‏ ‏حَدَّثَنَا ‏ ‏أُمَيَّةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَأَبُو عُمَرَ الضَّرِيرُ ‏ ‏الْمَعْنَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لُوطٌ ‏ { ‏لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَى رُكْنٍ شَدِيدٍ ‏} ‏قَالَ قَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَكِنَّهُ عَنَى عَشِيرَتَهُ فَمَا بَعَثَ اللَّهُ عَزَّ وَجَلَّ بَعْدَهُ نَبِيًّا إِلَّا بَعَثَهُ فِي ‏ ‏ذُرْوَةِ ‏ ‏قَوْمِهِ ‏ ‏قَالَ ‏ ‏أَبُو عُمَرَ ‏ ‏فَمَا بَعَثَ اللَّهُ عَزَّ وَجَلَّ نَبِيًّا بَعْدَهُ إِلَّا فِي ‏ ‏مَنَعَةٍ ‏ ‏مِنْ قَوْمِهِ ‏","","",""],[10484,10484,"","","‏ ‏حَدَّثَنَا ‏ ‏أُمَيَّةُ بْنُ خَالِدٍ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏رَفَعَ الْحَدِيثَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏كَانَ مَلَكُ الْمَوْتِ يَأْتِي النَّاسَ عِيَانًا قَالَ فَأَتَى ‏ ‏مُوسَى ‏ ‏فَلَطَمَهُ ‏ ‏فَفَقَأَ ‏ ‏عَيْنَهُ فَأَتَى رَبَّهُ عَزَّ وَجَلَّ فَقَالَ يَا رَبِّ عَبْدُكَ ‏ ‏مُوسَى ‏ ‏فَقَأَ عَيْنِي وَلَوْلَا كَرَامَتُهُ عَلَيْكَ لَعَنُفْتُ بِهِ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏لَشَقَقْتُ عَلَيْهِ ‏ ‏فَقَالَ لَهُ اذْهَبْ إِلَى عَبْدِي فَقُلْ لَهُ فَلْيَضَعْ يَدَهُ عَلَى جِلْدِ أَوْ ‏ ‏مَسْكِ ‏ ‏ثَوْرٍ فَلَهُ بِكُلِّ شَعَرَةٍ وَارَتْ يَدُهُ سَنَةٌ فَأَتَاهُ فَقَالَ لَهُ مَا بَعْدَ هَذَا قَالَ الْمَوْتُ قَالَ فَالْآنَ قَالَ فَشَمَّهُ شَمَّةً فَقَبَضَ رُوحَهُ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏فَرَدَّ اللَّهُ عَزَّ وَجَلَّ عَيْنَهُ ‏ ‏وَكَانَ يَأْتِي النَّاسَ خُفْيَةً ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مَلَكُ الْمَوْتِ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَذَكَرَهُ ‏","","",""],[10485,10485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏كُلُّ أُمَّةٍ ‏ ‏تُدْعَى إِلَى كِتَابِهَا ‏} ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّاسُ يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ فَقَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ فَقَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ فَإِنَّكُمْ تَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ كَذَلِكَ يَجْمَعُ اللَّهُ النَّاسَ فَيَقُولُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ فَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ وَمَنْ كَانَ يَعْبُدُ الشَّمْسَ الشَّمْسَ وَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ ‏ ‏الطَّوَاغِيتَ ‏ ‏الطَّوَاغِيتَ ‏ ‏وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ نَعُوذُ بِاللَّهِ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا عَزَّ وَجَلَّ فَإِذَا جَاءَنَا رَبُّنَا عَرَفْنَاهُ قَالَ فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي الصُّورَةِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا فَيَتَّبِعُونَهُ قَالَ وَيُضْرَبُ بِجِسْرٍ عَلَى جَهَنَّمَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكُونُ أَوَّلَ مَنْ ‏ ‏يُجِيزُ ‏ ‏وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ وَبِهَا كَلَالِيبُ مِثْلُ شَوْكِ ‏ ‏السَّعْدَانِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهَا مِثْلُ شَوْكِ ‏ ‏السَّعْدَانِ ‏ ‏غَيْرَ أَنَّهُ لَا يَعْلَمُ قَدْرَ عِظَمِهَا إِلَّا اللَّهُ عَزَّ وَجَلَّ فَتَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ فَمِنْهُمْ الْمُوبَقُ بِعَمَلِهِ وَمِنْهُمْ ‏ ‏الْمُخَرْدَلُ ‏ ‏ثُمَّ ‏ ‏يَنْجُو حَتَّى إِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ مِنْ النَّارِ مَنْ أَرَادَ أَنْ يَرْحَمَ مِمَّنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوهُمْ فَيَعْرِفُونَهُمْ بِعَلَامَةِ آثَارِ السُّجُودِ وَحَرَّمَ اللَّهُ عَزَّ وَجَلَّ عَلَى النَّارِ أَنْ تَأْكُلَ مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏أَثَرَ السُّجُودِ فَيُخْرِجُونَهُمْ مِنْ النَّارِ قَدْ ‏ ‏امْتَحَشُوا ‏ ‏فَيُصَبُّ عَلَيْهِمْ مِنْ مَاءٍ يُقَالُ لَهُ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ وَيَبْقَى رَجُلٌ يُقْبِلُ بِوَجْهِهِ إِلَى النَّارِ فَيَقُولُ أَيْ رَبِّ قَدْ ‏ ‏قَشَبَنِي ‏ ‏رِيحُهَا وَأَحْرَقَنِي ‏ ‏ذَكَاؤُهَا ‏ ‏فَاصْرِفْ وَجْهِي عَنْ النَّارِ قَالَ فَلَا يَزَالُ يَدْعُو اللَّهَ عَزَّ وَجَلَّ حَتَّى يَقُولَ فَلَعَلَّ إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ فَيَصْرِفُ وَجْهَهُ عَنْ النَّارِ ثُمَّ يَقُولُ بَعْدَ ذَلِكَ يَا رَبِّ قَرِّبْنِي إِلَى بَابِ الْجَنَّةِ فَيَقُولُ أَوَلَيْسَ قَدْ زَعَمْتَ أَنَّكَ لَا تَسْأَلُنِي غَيْرَهُ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَلَا يَزَالُ يَدْعُو حَتَّى يَقُولَ فَلَعَلِّي إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ وَيُعْطِي اللَّهَ عَزَّ وَجَلَّ مِنْ عُهُودٍ وَمَوَاثِيقَ أَنْ لَا يَسْأَلَهُ غَيْرَهُ فَيُقَرِّبُهُ إِلَى بَابِ الْجَنَّةِ فَإِذَا دَنَا مِنْهَا ‏ ‏انْفَهَقَتْ ‏ ‏لَهُ الْجَنَّةُ فَإِذَا رَأَى مَا فِيهَا مِنْ ‏ ‏الْحَبْرَةِ ‏ ‏وَالسُّرُورِ يَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ فَيَقُولُ أَوَلَيْسَ قَدْ زَعَمْتَ أَنْ لَا تَسْأَلَنِي غَيْرَهُ أَوْ قَالَ فَيَقُولُ أَوَلَيْسَ قَدْ أَعْطَيْتَ عَهْدَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَنِي غَيْرَهُ فَيَقُولُ يَا رَبِّ لَا تَجْعَلْنِي أَشْقَى خَلْقِكَ فَلَا يَزَالُ يَدْعُو اللَّهَ عَزَّ وَجَلَّ حَتَّى يَضْحَكَ فَإِذَا ضَحِكَ مِنْهُ أَذِنَ لَهُ بِالدُّخُولِ فِيهَا فَإِذَا دَخَلَ قِيلَ لَهُ تَمَنَّ مِنْ كَذَا فَيَتَمَنَّى ثُمَّ يُقَالُ تَمَنَّ مِنْ كَذَا فَيَتَمَنَّى حَتَّى تَنْقَطِعَ بِهِ الْأَمَانِيُّ فَيُقَالُ هَذَا لَكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏جَالِسٌ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَا يُغَيِّرُ عَلَيْهِ شَيْءٌ مِنْ قَوْلِهِ حَتَّى انْتَهَى إِلَى قَوْلِهِ هَذَا لَكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا لَكَ وَعَشَرَةُ أَمْثَالِهِ مَعَهُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَفِظْتُ وَمِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ ‏","","",""],[10486,10486,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقُّ الضِّيَافَةِ ثَلَاثَةُ أَيَّامٍ فَمَا أَصَابَ بَعْدَ ذَلِكَ فَهُوَ صَدَقَةٌ ‏","","",""],[10487,10487,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْبَرِي هَذَا عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ وَمَا بَيْنَ حُجْرَتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏","","",""],[10488,10488,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي وَاللَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ يَجِدُ ‏ ‏ضَالَّتَهُ ‏ ‏بِالْفَلَاةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏أُرَاهُ ضَالَّتَهُ ‏ ‏وَمَنْ تَقَرَّبَ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا وَمَنْ تَقَرَّبَ ‏ ‏إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ بَاعًا فَإِذَا أَقْبَلَ إِلَيَّ يَمْشِي أَقْبَلْتُ إِلَيْهِ أُهَرْوِلُ ‏","","",""],[10489,10489,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْحُبَابِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ ‏ ‏أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي ‏ ‏الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي ‏","","",""],[10490,10490,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَالْيَدَانِ تَزْنِيَانِ وَالرِّجْلَانِ تَزْنِيَانِ وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ ‏","","",""],[10491,10491,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَغْنَمًا قَطُّ إِلَّا قَسَمَ لِي إِلَّا ‏ ‏خَيْبَرَ ‏ ‏فَإِنَّهَا كَانَتْ لِأَهْلِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏خَاصَّةً ‏ ‏وَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَأَبُو مُوسَى ‏ ‏جَاءَا بَيْنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَخَيْبَرَ ‏","","",""],[10492,10492,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ طُولُ ‏ ‏آدَمَ ‏ ‏سِتِّينَ ذِرَاعًا فِي سَبْعَةِ أَذْرُعٍ عَرْضًا ‏","","",""],[10493,10493,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا يَغْتَسِلُونَ عُرَاةً وَكَانَ ‏ ‏نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ الْحَيَاءُ ‏ ‏وَالْخَفَرُ ‏ ‏فَكَانَ يَسْتَتِرُ إِذَا اغْتَسَلَ فَطَعَنُوا فِيهِ يُعَيِّرُوهُ قَالَ فَبَيْنَمَا ‏ ‏نَبِيُّ اللَّهِ ‏ ‏يَغْتَسِلُ يَوْمًا إِذْ وَضَعَ ثِيَابَهُ عَلَى صَخْرَةٍ فَانْطَلَقَتْ الصَّخْرَةُ فَاتَّبَعَهَا ‏ ‏نَبِيُّ اللَّهِ ‏ ‏ضَرْبًا بِالْعَصَا ثَوْبِي يَا حَجَرُ ثَوْبِي يَا حَجَرُ حَتَّى انْتَهَتْ بِهِ إِلَى ‏ ‏مَلَإٍ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَتَوَسَّطَتْهُمْ فَقَامَتْ فَأَخَذَ ‏ ‏نَبِيُّ اللَّهِ ‏ ‏ثِيَابَهُ فَنَظَرُوا إِلَى أَحْسَنِ النَّاسِ خَلْقًا وَأَعْدَلِهِمْ صُورَةً فَقَالَ ‏ ‏الْمَلَأُ ‏ ‏قَاتَلَ اللَّهُ أَفَّاكِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَكَانَتْ بَرَاءَتُهُ الَّتِي بَرَّأَهُ اللَّهُ ‏","","",""],[10494,10494,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْضَلُ صَلَاةٍ بَعْدَ الْمَفْرُوضَةِ صَلَاةُ اللَّيْلِ وَأَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الَّذِي تَدْعُونَهُ الْمُحَرَّمَ ‏","","",""],[10495,10495,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اقْتَتَلَتْ ‏ ‏امْرَأَتَانِ مِنْ ‏ ‏هُذَيْلٍ ‏ ‏فَرَمَتْ ‏ ‏إِحْدَاهُمَا ‏ ‏الْأُخْرَى ‏ ‏بِحَجَرٍ فَقَتَلَتْهَا وَمَا فِي بَطْنِهَا فَاخْتَصَمُوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏دِيَةَ ‏ ‏جَنِينِهَا ‏ ‏غُرَّةٌ ‏ ‏عَبْدٌ أَوْ وَلِيدَةٌ وَقَضَى بِدِيَةِ ‏ ‏الْمَرْأَةِ ‏ ‏عَلَى ‏ ‏قَاتِلَتِهَا ‏ ‏فَقَالَ ‏ ‏حَمَلُ بْنُ نَابِغَةَ الْهُذَلِيُّ ‏ ‏كَيْفَ أَغْرَمُ مَنْ لَا شَرِبَ وَلَا أَكَلَ وَلَا نَطَقَ وَلَا ‏ ‏اسْتَهَلَّ ‏ ‏فَمِثْلُ ذَلِكَ ‏ ‏يُطَلُّ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هُوَ مِنْ إِخْوَانِ ‏ ‏الْكُهَّانِ ‏ ‏مِنْ أَجْلِ ‏ ‏سَجْعِهِ ‏ ‏الَّذِي ‏ ‏سَجَعَ ‏","","",""],[10496,10496,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏عَبْدَ اللَّهِ بْنَ حُذَافَةَ ‏ ‏يَطُوفُ فِي ‏ ‏مِنًى ‏ ‏أَنْ لَا تَصُومُوا هَذِهِ الْأَيَّامَ فَإِنَّهَا أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[10497,10497,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ الْحُرِّ النَّخَعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنْ ‏ ‏كُمَيْلِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلَكَ الْأَكْثَرُونَ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَقَلِيلٌ مَا هُمْ فَمَشَيْتُ مَعَهُ ثُمَّ قَالَ أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ ثُمَّ قَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏تَدْرِي مَا حَقُّ اللَّهِ عَلَى الْعِبَادِ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ حَقُّهُ أَنْ يَعْبُدُوهُ لَا يُشْرِكُوا بِهِ شَيْئًا ثُمَّ قَالَ تَدْرِي مَا حَقُّ الْعِبَادِ عَلَى اللَّهِ فَإِنَّ حَقَّهُمْ عَلَى اللَّهِ إِذَا فَعَلُوا ذَلِكَ أَنْ لَا يُعَذِّبَهُمْ قُلْتُ أَفَلَا أُخْبِرُهُمْ قَالَ دَعْهُمْ فَلْيَعْمَلُوا ‏","","",""],[10498,10498,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏ابْنَ حُنَيْنٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ رَجُلًا يَقْرَأُ قُلْ هُوَ اللَّهُ أَحَدٌ حَتَّى خَتَمَهَا فَقَالَ ‏ ‏وَجَبَتْ قِيلَ يَا رَسُولَ اللَّهِ مَا وَجَبَتْ قَالَ الْجَنَّةُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَأَرَدْتُ أَنْ آتِيَهُ فَأُبَشِّرَهُ فَآثَرْتُ الْغَدَاءَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفَرِقْتُ أَنْ يَفُوتَنِي الْغَدَاءُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ رَجَعْتُ إِلَى الرَّجُلِ فَوَجَدْتُهُ قَدْ ذَهَبَ ‏","","",""],[10499,10499,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ ابْنِ ‏ ‏آدَمَ ‏ ‏لَهُ حَظُّهُ مِنْ الزِّنَا فَزِنَا الْعَيْنَيْنِ النَّظَرُ وَزِنَا الْيَدَيْنِ ‏ ‏الْبَطْشُ ‏ ‏وَزِنَا الرِّجْلَيْنِ الْمَشْيُ وَزِنَا الْفَمِ الْقُبَلُ وَالْقَلْبُ ‏ ‏يَهْوَى ‏ ‏وَيَتَمَنَّى وَيُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ الْفَرْجُ ‏ ‏وَحَلَّقَ ‏ ‏عَشْرَةً ثُمَّ أَدْخَلَ أُصْبُعَهُ السَّبَّابَةَ فِيهَا يَشْهَدُ عَلَى ذَلِكَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَحْمُهُ وَدَمُهُ ‏","","",""],[10500,10500,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ نِسَاءُ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْأَفُهُ بِزَوْجٍ عَلَى قِلَّةِ ذَاتِ يَدِهِ ثُمَّ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَقَدْ عَلِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ابْنَةَ ‏ ‏عِمْرَانَ ‏ ‏لَمْ تَرْكَبْ الْإِبِلَ ‏","","",""],[10501,10501,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَيُّوبَ ‏ ‏مِنْ وَلَدِ ‏ ‏جَرِيرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُذْكَرُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَفَرَّقُ الْمُتَبَايِعَانِ عَنْ بَيْعٍ إِلَّا عَنْ تَرَاضٍ ‏","","",""],[10502,10502,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏مِنْ وَلَدِ ‏ ‏جَرِيرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُذْكَرُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَلَدٍ لَهَا مَرِيضٍ يَدْعُو لَهُ بِالشِّفَاءِ وَالْعَافِيَةِ فَقَالَتْ يَا رَسُولَ اللَّهِ قَدْ ‏ ‏مَاتَ لِي ثَلَاثَةٌ قَالَ فِي الْإِسْلَامِ قَالَتْ فِي الْإِسْلَامِ لَمْ ‏ ‏يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏يَحْتَسِبُهُمْ إِلَّا احْتَظَرَ ‏ ‏بِحَظِيرٍ مِنْ النَّارِ ‏","","",""],[10503,10503,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ قَالَ ‏ ‏اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْأَرَضِينَ وَرَبَّنَا وَرَبَّ كُلِّ شَيْءٍ ‏ ‏فَالِقَ ‏ ‏الْحَبِّ وَالنَّوَى مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ ‏ ‏بِنَاصِيَتِهِ ‏ ‏أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنْ الْفَقْرِ ‏","","",""],[10504,10504,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏صَحَّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ وَإِنْ صَامَ وَصَلَّى وَزَعَمَ أَنَّهُ مُسْلِمٌ مَنْ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا اؤْتُمِنَ خَانَ ‏","","",""],[10505,10505,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ يَنْقُصُ الْعِلْمُ وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ ‏","","",""],[10506,10506,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شَرِيكٍ الْعَامِرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏مَرْوَانَ ‏ ‏يَقُولُ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيُوشِكَنَّ رَجُلٌ ‏ ‏يَتَمَنَّى أَنَّهُ ‏ ‏خَرَّ ‏ ‏مِنْ عِنْدِ ‏ ‏الثُّرَيَّا ‏ ‏وَأَنَّهُ لَمْ يَنَلْ مِنْ أَمْرِ النَّاسِ شَيْئًا ‏","","",""],[10507,10507,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ هَلَاكَ ‏ ‏الْعَرَبِ ‏ ‏عَلَى يَدَيْ غِلْمَةٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏بِئْسَ الْغِلْمَةُ أُولَئِكَ ‏","","",""],[10508,10508,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَغَارُ وَإِنَّ الْمُؤْمِنَ يَغَارُ وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْمُؤْمِنُ يَغَارُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[10509,10509,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلُّونَ بِكُمْ فَإِنْ أَصَابُوا فَلَكُمْ وَلَهُمْ وَإِنْ أَخْطَئُوا فَلَكُمْ وَعَلَيْهِمْ ‏","","",""],[10510,10510,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ضِرْسُ الْكَافِرِ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏وَفَخِذُهُ مِثْلُ ‏ ‏الْبَيْضَاءِ ‏ ‏وَمَقْعَدُهُ مِنْ النَّارِ كَمَا بَيْنَ ‏ ‏قُدَيْدٍ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏وَكَثَافَةُ جِلْدِهِ اثْنَانِ وَأَرْبَعُونَ ذِرَاعًا بِذِرَاعِ الْجَبَّارِ ‏","","",""],[10511,10511,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ الضَّرِيرُ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً إِنَّ لَهُ لَسَبْعَ دَرَجَاتٍ وَهُوَ عَلَى السَّادِسَةِ وَفَوْقَهُ السَّابِعَةُ وَإِنَّ لَهُ لَثَلَاثَ مِائَةِ خَادِمٍ ‏ ‏وَيُغْدَى عَلَيْهِ وَيُرَاحُ كُلَّ يَوْمٍ ثَلَاثُ مِائَةِ صَحْفَةٍ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا قَالَ ‏ ‏مِنْ ذَهَبٍ فِي كُلِّ صَحْفَةٍ لَوْنٌ لَيْسَ فِي الْأُخْرَى وَإِنَّهُ لَيَلَذُّ أَوَّلَهُ كَمَا يَلَذُّ آخِرَهُ وَإِنَّهُ لَيَقُولُ يَا رَبِّ لَوْ أَذِنْتَ لِي لَأَطْعَمْتُ أَهْلَ الْجَنَّةِ وَسَقَيْتُهُمْ لَمْ يَنْقُصْ مِمَّا عِنْدِي شَيْءٌ وَإِنَّ لَهُ مِنْ الْحُورِ الْعِينِ لَاثْنَيْنِ وَسَبْعِينَ زَوْجَةً سِوَى أَزْوَاجِهِ مِنْ الدُّنْيَا وَإِنَّ الْوَاحِدَةَ مِنْهُنَّ لَيَأْخُذُ مَقْعَدُهَا قَدْرَ مِيلٍ مِنْ الْأَرْضِ ‏","","",""],[10512,10512,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَشَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَجُلٌ مِنْ الْمَسْجِدِ بَعْدَمَا أَذَّنَ الْمُؤَذِّنُ فَقَالَ أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَفِي حَدِيثِ ‏ ‏شَرِيكٍ ‏ ‏ثُمَّ قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ فِي الْمَسْجِدِ فَنُودِيَ بِالصَّلَاةِ فَلَا يَخْرُجْ أَحَدُكُمْ حَتَّى يُصَلِّيَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ فِي الْمَسْجِدِ فَنُودِيَ بِالصَّلَاةِ فَلَا يَخْرُجْ أَحَدُكُمْ حَتَّى يُصَلِّيَ ‏","","",""],[10513,10513,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ حَتَّى ‏ ‏تَهَوَّرَ ‏ ‏اللَّيْلُ فَذَهَبَ ثُلُثُهُ أَوْ قَرَابَتُهُ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ فَإِذَا النَّاسُ ‏ ‏عِزُونَ ‏ ‏وَإِذَا هُمْ قَلِيلٌ قَالَ فَغَضِبَ غَضَبًا مَا أَعْلَمُ أَنِّي رَأَيْتُهُ غَضِبَ غَضَبًا قَطُّ أَشَدَّ مِنْهُ ثُمَّ قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا دَعَا النَّاسَ إِلَى ‏ ‏عَرْقٍ ‏ ‏أَوْ مِرْمَاتَيْنِ أَتَوْهُ لِذَلِكَ وَلَمْ يَتَخَلَّفُوا وَهُمْ يَتَخَلَّفُونَ عَنْ هَذِهِ الصَّلَاةِ لَقَدْ هَمَمْتُ أَنْ آمُرَ رَجُلًا ‏ ‏يُصَلِّي بِالنَّاسِ وَأَتَّبِعَ هَذِهِ الدُّورَ الَّتِي تَخَلَّفَ أَهْلُوهَا عَنْ هَذِهِ ‏ ‏فَأُضْرِمَهَا ‏ ‏عَلَيْهِمْ بِالنِّيرَانِ ‏","","",""],[10514,10514,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ يَوْمَ الْقِيَامَةِ لَوْنُ جُرْحِهِ لَوْنُ الدَّمِ وَرِيحُهُ رِيحُ الْمِسْكِ ‏","","",""],[10515,10515,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْحَارِثِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْتَ الَّذِي ‏ ‏تَنْهَى النَّاسَ أَنْ يُصَلُّوا فِي نِعَالِهِمْ قَالَ هَا وَرَبِّ هَذِهِ الْحُرْمَةِ هَا وَرَبِّ هَذِهِ الْحُرْمَةِ لَقَدْ رَأَيْتُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَى هَذَا الْمَقَامِ فِي نَعْلَيْهِ ثُمَّ انْصَرَفَ وَهُمَا عَلَيْهِ ‏","","",""],[10516,10516,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَمَمْتُمْ النَّاسَ فَخَفِّفُوا فَإِنَّ فِيهِمْ الْكَبِيرَ وَالضَّعِيفَ وَالصَّغِيرَ ‏","","",""],[10517,10517,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَنْ يُنْجِيَ أَحَدَكُمْ عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏ ‏فَسَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَاغْدُوا ‏ ‏وَرُوحُوا ‏ ‏وَشَيْءٌ مِنْ ‏ ‏الدُّلْجَةِ ‏ ‏وَالْقَصْدَ ‏ ‏الْقَصْدَ ‏ ‏تَبْلُغُوا ‏","","",""],[10518,10518,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَامَ وَفِي يَدِهِ ‏ ‏غَمْرٌ ‏ ‏وَلَمْ يَغْسِلْهُ فَأَصَابَهُ شَيْءٌ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ ‏","","",""],[10519,10519,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ ‏","","",""],[10520,10520,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ الرَّجُلُ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[10521,10521,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ ‏ ‏السَّاعَةُ حَتَّى يَتَقَارَبَ الزَّمَانُ فَتَكُونَ السَّنَةُ كَالشَّهْرِ وَيَكُونَ الشَّهْرُ كَالْجُمُعَةِ وَتَكُونَ الْجُمُعَةُ كَالْيَوْمِ وَيَكُونَ الْيَوْمُ كَالسَّاعَةِ وَتَكُونَ السَّاعَةُ كَاحْتِرَاقِ السَّعَفَةِ الْخُوصَةُ ‏ ‏زَعَمَ ‏ ‏سُهَيْلٌ ‏","","",""],[10522,10522,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمْ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏حَكَمًا ‏ ‏مُقْسِطًا ‏ ‏يَكْسِرُ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ ‏ ‏وَيَضَعُ ‏ ‏الْجِزْيَةَ ‏ ‏وَيَفِيضُ ‏ ‏الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ ‏","","",""],[10523,10523,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏أَخِي ‏ ‏أَبِي مَرْثَدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏تَصَدَّقَ ‏ ‏أَحَدٌ ‏ ‏بِصَدَقَةٍ ‏ ‏مِنْ طَيِّبٍ وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبَ إِلَّا أَخَذَهَا الرَّحْمَنُ عَزَّ وَجَلَّ بِيَمِينِهِ وَإِنْ كَانَتْ تَمْرَةً ‏ ‏فَتَرْبُو ‏ ‏لَهُ فِي كَفِّ الرَّحْمَنِ حَتَّى تَكُونَ أَعْظَمَ مِنْ الْجَبَلِ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏","","",""],[10524,10524,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى الْعَامِرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَاتَتْ الْمَرْأَةُ ‏ ‏هَاجِرَةً ‏ ‏لِفِرَاشِ زَوْجِهَا لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تَرْجِعَ ‏","","",""],[10525,10525,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏هِلَالَ بْنَ زَيْدٍ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي مَازِنِ بْنِ شَيْبَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذِهِ الْحَبَّةَ السَّوْدَاءَ ‏ ‏يَعْنِي ‏ ‏الشُّونِيزَ ‏ ‏شِفَاءٌ مِنْ كُلِّ شَيْءٍ لَيْسَ ‏ ‏السَّامَ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَالسَّامُ الْمَوْتُ ‏","","",""],[10526,10526,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَبَاحٍ ‏ ‏قَالَ ‏ ‏وَفَدَتْ وُفُودٌ إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَا فِيهِمْ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏فِي رَمَضَانَ فَجَعَلَ بَعْضُنَا يَصْنَعُ لِبَعْضٍ الطَّعَامَ قَالَ وَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُكْثِرُ مَا يَدْعُونَا ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏يُكْثِرُ أَنْ يَدْعُوَنَا ‏ ‏إِلَى رَحْلِهِ قَالَ فَقُلْتُ أَلَا أَصْنَعُ طَعَامًا فَأَدْعُوَهُمْ إِلَى رَحْلِي قَالَ فَأَمَرْتُ بِطَعَامٍ يُصْنَعُ وَلَقِيتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مِنْ الْعِشَاءِ قَالَ قُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏الدَّعْوَةُ عِنْدِي اللَّيْلَةَ قَالَ أَسَبَقْتَنِي ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏قُلْتُ نَعَمْ ‏ ‏قَالَ فَدَعَوْتُهُمْ فَهُمْ عِنْدِي ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَلَا أُعْلِمُكُمْ بِحَدِيثٍ مِنْ حَدِيثِكُمْ يَا مَعَاشِرَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ فَذَكَرَ فَتْحَ ‏ ‏مَكَّةَ ‏ ‏قَالَ أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَبَعَثَ ‏ ‏الزُّبَيْرَ ‏ ‏عَلَى إِحْدَى ‏ ‏الْمُجَنِّبَتَيْنِ ‏ ‏وَبَعَثَ ‏ ‏خَالِدًا ‏ ‏عَلَى ‏ ‏الْمُجَنِّبَةِ ‏ ‏الْأُخْرَى وَبَعَثَ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏عَلَى ‏ ‏الْحُسَّرِ ‏ ‏فَأَخَذُوا ‏ ‏بَطْنَ الْوَادِي ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كَتِيبَتِهِ قَالَ وَقَدْ ‏ ‏وَبَّشَتْ ‏ ‏قُرَيْشٌ ‏ ‏أَوْبَاشَهَا قَالَ فَقَالُوا نُقَدِّمُ هَؤُلَاءِ فَإِنْ كَانَ لَهُمْ شَيْءٌ كُنَّا مَعَهُمْ وَإِنْ أُصِيبُوا أَعْطَيْنَا الَّذِي سُئِلْنَا قَالَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَنَظَرَ فَرَآنِي فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقُلْتُ لَبَّيْكَ رَسُولَ اللَّهِ قَالَ فَقَالَ اهْتِفْ لِي ‏ ‏بِالْأَنْصَارِ ‏ ‏وَلَا يَأْتِينِي إِلَّا أَنْصَارِيٌّ فَهَتَفْتُ بِهِمْ فَجَاءُوا فَأَطَافُوا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَرَوْنَ إِلَى ‏ ‏أَوْبَاشِ ‏ ‏قُرَيْشٍ ‏ ‏وَأَتْبَاعِهِمْ ثُمَّ قَالَ بِيَدَيْهِ إِحْدَاهُمَا عَلَى الْأُخْرَى حَصْدًا حَتَّى تُوَافُونِي ‏ ‏بِالصَّفَا ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَانْطَلَقْنَا فَمَا يَشَاءُ أَحَدٌ مِنَّا أَنْ يَقْتُلَ مِنْهُمْ مَا شَاءَ وَمَا أَحَدٌ يُوَجِّهُ إِلَيْنَا مِنْهُمْ شَيْئًا قَالَ فَقَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أُبِيحَتْ ‏ ‏خَضْرَاءُ ‏ ‏قُرَيْشٍ ‏ ‏لَا ‏ ‏قُرَيْشَ ‏ ‏بَعْدَ الْيَوْمِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَغْلَقَ بَابَهُ فَهُوَ آمِنٌ وَمَنْ دَخَلَ دَارَ ‏ ‏أَبِي سُفْيَانَ ‏ ‏فَهُوَ آمِنٌ قَالَ فَغَلَّقَ النَّاسُ أَبْوَابَهُمْ قَالَ فَأَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْحَجَرِ فَاسْتَلَمَهُ ثُمَّ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏قَالَ وَفِي يَدِهِ قَوْسٌ أَخَذَ ‏ ‏بِسِيَةِ ‏ ‏الْقَوْسِ ‏ ‏قَالَ ‏ ‏فَأَتَى ‏ ‏فِي طَوَافِهِ عَلَى صَنَمٍ إِلَى ‏ ‏جَنْبٍ ‏ ‏يَعْبُدُونَهُ قَالَ فَجَعَلَ يَطْعَنُ بِهَا فِي عَيْنِهِ وَيَقُولُ ‏ { ‏جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ ‏} ‏قَالَ ثُمَّ أَتَى ‏ ‏الصَّفَا ‏ ‏فَعَلَاهُ حَيْثُ يُنْظَرُ إِلَى ‏ ‏الْبَيْتِ ‏ ‏فَرَفَعَ يَدَيْهِ فَجَعَلَ يَذْكُرُ اللَّهَ بِمَا شَاءَ أَنْ يَذْكُرَهُ ‏ ‏وَيَدْعُوهُ قَالَ ‏ ‏وَالْأَنْصَارُ ‏ ‏تَحْتَهُ قَالَ يَقُولُ بَعْضُهُمْ لِبَعْضٍ أَمَّا الرَّجُلُ فَأَدْرَكَتْهُ رَغْبَةٌ فِي قَرْيَتِهِ وَرَأْفَةٌ بِعَشِيرَتِهِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَجَاءَ الْوَحْيُ وَكَانَ إِذَا جَاءَ لَمْ يَخْفَ عَلَيْنَا فَلَيْسَ أَحَدٌ مِنْ النَّاسِ يَرْفَعُ ‏ ‏طَرْفَهُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏يُقْضَى ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فَلَمَّا قُضِيَ الْوَحْيُ رَفَعَ رَأْسَهُ ‏ ‏ثُمَّ قَالَ يَا مَعَاشِرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَقُلْتُمْ أَمَّا الرَّجُلُ فَأَدْرَكَتْهُ رَغْبَةٌ فِي قَرْيَتِهِ وَرَأْفَةٌ بِعَشِيرَتِهِ قَالُوا قُلْنَا ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ فَمَا اسْمِي إِذًا كَلَّا إِنِّي عَبْدُ اللَّهِ وَرَسُولُهُ هَاجَرْتُ إِلَى اللَّهِ وَإِلَيْكُمْ فَالْمَحْيَا مَحْيَاكُمْ وَالْمَمَاتُ مَمَاتُكُمْ قَالَ فَأَقْبَلُوا إِلَيْهِ يَبْكُونَ وَيَقُولُونَ وَاللَّهِ مَا قُلْنَا الَّذِي قُلْنَا إِلَّا ‏ ‏الضِّنَّ ‏ ‏بِاللَّهِ وَرَسُولِهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ اللَّهَ وَرَسُولَهُ يُصَدِّقَانِكُمْ وَيَعْذُرَانِكُمْ ‏","","",""],[10527,10527,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّهُ أَكْذَبُ الْحَدِيثِ وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا تَنَافَسُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا كَمَا أَمَرَكُمْ اللَّهُ ‏","","",""],[10528,10528,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ وَهُوَ شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَغَارُ وَإِنَّ الْمُؤْمِنَ يَغَارُ وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ ‏","","",""],[10529,10529,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏مَوْلَى آلِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُهُ يَقُولُ قَالَ ‏ ‏مُحَمَّدٌ رَسُولُ اللَّهِ أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاحِبُ هَذِهِ الْحُجْرَةِ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[10530,10530,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[10531,10531,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنِينِ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ ‏ ‏بَنِي لِحْيَانَ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏سَقَطَ مَيِّتًا ‏ ‏بِغُرَّةٍ ‏ ‏عَبْدٍ أَوْ أَمَةٍ ‏ ‏ثُمَّ إِنَّ الْمَرْأَةَ ‏ ‏الَّتِي قَضَى عَلَيْهَا ‏ ‏بِالْغُرَّةِ ‏ ‏تُوُفِّيَتْ فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَنَّ مِيرَاثَهَا لِبَنِيهَا وَزَوْجِهَا وَأَنَّ ‏ ‏الْعَقْلَ ‏ ‏عَلَى ‏ ‏عَصَبَتِهَا ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ ثُمَّ إِنَّ الْمَرْأَةَ الَّتِي ‏ ‏قَضَى ‏ ‏عَلَيْهَا ‏ ‏بِالْغُرَّةِ ‏ ‏تُوُفِّيَتْ ‏","","",""],[10532,10532,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَظْهَرُ الْفِتَنُ وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قُلْنَا وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ وَقَالَ وَيُقْبَضُ الْعِلْمُ ‏","","",""],[10533,10533,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏كَثِيرٌ ‏ ‏مَرَّةً حَدِيثٌ رَفَعَهُ ‏ ‏قَالَ ‏ ‏النَّاسُ مَعَادِنُ كَمَعَادِنِ الْفِضَّةِ وَالذَّهَبِ خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا وَالْأَرْوَاحُ جُنُودٌ ‏ ‏مُجَنَّدَةٌ ‏ ‏مَا ‏ ‏تَعَارَفَ ‏ ‏مِنْهَا ائْتَلَفَ وَمَا ‏ ‏تَنَاكَرَ ‏ ‏مِنْهَا اخْتَلَفَ ‏","","",""],[10534,10534,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَسْأَلَنَّكُمْ النَّاسُ عَنْ كُلِّ شَيْءٍ حَتَّى يَقُولُوا اللَّهُ خَلَقَ كُلَّ شَيْءٍ فَمَنْ خَلَقَهُ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَحَدَّثَنِي ‏ ‏نَجَبَةُ بْنُ صَبِيغٍ السُّلَمِيُّ ‏ ‏أَنَّهُ رَأَى رَكْبًا أَتَوْا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَسَأَلُوهُ عَنْ ذَلِكَ فَقَالَ اللَّهُ أَكْبَرُ مَا حَدَّثَنِي خَلِيلِي بِشَيْءٍ إِلَّا وَقَدْ رَأَيْتُهُ وَأَنَا أَنْتَظِرُهُ قَالَ ‏ ‏جَعْفَرٌ ‏ ‏بَلَغَنِي أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا سَأَلَكُمْ النَّاسُ عَنْ هَذَا فَقُولُوا اللَّهُ كَانَ قَبْلَ كُلِّ شَيْءٍ وَاللَّهُ خَلَقَ كُلَّ شَيْءٍ وَاللَّهُ كَائِنٌ بَعْدَ كُلِّ شَيْءٍ ‏","","",""],[10535,10535,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَدِيثٌ لَا أَحْسِبُهُ إِلَّا رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ وَاللَّهِ مَا أَخْشَى عَلَيْكُمْ الْفَقْرَ وَلَكِنْ أَخْشَى عَلَيْكُمْ التَّكَاثُرَ وَلَكِنْ أَخْشَى عَلَيْكُمْ الْعَمْدَ ‏","","",""],[10536,10536,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏أَكْثَرْتَ أَكْثَرْتَ قَالَ ‏ ‏فَلَوْ حَدَّثْتُكُمْ بِكُلِّ مَا سَمِعْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَرَمَيْتُمُونِي ‏ ‏بِالْقَشْعِ ‏ ‏وَلَمَا نَاظَرْتُمُونِي ‏","","",""],[10537,10537,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ إِنَّمَا يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ ‏","","",""],[10538,10538,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏عَبْدِي عِنْدَ ظَنِّهِ بِي وَأَنَا مَعَهُ إِذَا دَعَانِي ‏","","",""],[10539,10539,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلَاةِ فَتُقَامَ ثُمَّ أَخْرُجَ بِفِتْيَانِي مَعَهُمْ حُزَمُ الْحَطَبِ فَأُحَرِّقَ عَلَى قَوْمٍ فِي بُيُوتِهِمْ يَسْمَعُونَ النِّدَاءَ ثُمَّ لَا يَأْتُونَ الصَّلَاةَ ‏ ‏فَسَأَلَ ‏ ‏يَزِيدُ ‏ ‏أَفِي الْجُمُعَةِ هَذَا أَمْ فِي غَيْرِهَا قَالَ مَا سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَذْكُرُ جُمُعَةً وَلَا غَيْرَهَا إِلَّا هَكَذَا ‏","","",""],[10540,10540,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُكُمْ أَيَّتُهَا الْأُمَّةُ ‏ ‏كَمَثَلِ رَجُلٍ اسْتَوْقَدَ نَارًا بِلَيْلٍ فَأَقْبَلَتْ إِلَيْهَا هَذِهِ الْفَرَاشُ وَالدَّوَابُّ الَّتِي ‏ ‏تَغْشَى النَّارَ فَجَعَلَ يَذُبُّهَا وَتَغْلِبُهُ إِلَّا تَقَحُّمًا فِي النَّارِ وَأَنَا آخِذٌ ‏ ‏بِحُجَزِكُمْ ‏ ‏أَدْعُوكُمْ إِلَى الْجَنَّةِ وَتَغْلِبُونِي إِلَّا تَقَحُّمًا فِي النَّارِ ‏","","",""],[10541,10541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُونَ أَكْثَرْتَ ‏ ‏فَلَوْ حَدَّثْتُكُمْ بِكُلِّ مَا سَمِعْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَيْتُمُونِي ‏ ‏بِالْقَشْعِ ‏ ‏وَمَا نَاظَرْتُمُونِي ‏","","",""],[10542,10542,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَيُّوبَ الْمَوْصِلِيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ ‏","","",""],[10543,10543,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ يُسَلِّمُ عَلَيْهِ إِذَا لَقِيَهُ ‏ ‏وَيُشَمِّتُهُ ‏ ‏إِذَا عَطَسَ ‏ ‏وَيَعُودُهُ ‏ ‏إِذَا مَرِضَ وَيَشْهَدُ جِنَازَتَهُ إِذَا مَاتَ وَيُجِيبُهُ إِذَا ‏ ‏دَعَاهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏غَرِيبٌ ‏ ‏يَعْنِي هَذَا الْحَدِيثَ ‏","","",""],[10544,10544,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ ‏ ‏وَالْحَبَشَةُ ‏ ‏يَلْعَبُونَ فَزَجَرَهُمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُمْ يَا ‏ ‏عُمَرُ ‏ ‏فَإِنَّهُمْ ‏ ‏بَنُو أَرْفِدَةَ ‏","","",""],[10545,10545,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏وَأَبُو الْمُغِيرَةِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏أَنَا مَعَ عَبْدِي إِذَا هُوَ ذَكَرَنِي وَتَحَرَّكَتْ شَفَتَاهُ ‏","","",""],[10546,10546,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَادَ أَنْ يَنْفِرَ مِنْ ‏ ‏مِنًى ‏ ‏قَالَ ‏ ‏نَحْنُ نَازِلُونَ غَدًا إِنْ شَاءَ اللَّهُ تَعَالَى ‏ ‏بِالْمُحَصَّبِ ‏ ‏بِخَيْفِ ‏ ‏بَنِي كِنَانَةَ ‏ ‏حَيْثُ ‏ ‏تَقَاسَمُوا ‏ ‏عَلَى الْكُفْرِ وَذَاكَ أَنَّ ‏ ‏قُرَيْشًا ‏ ‏تَقَاسَمُوا ‏ ‏عَلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَعَلَى ‏ ‏بَنِي الْمُطَّلِبِ ‏ ‏أَنْ لَا ‏ ‏يُنَاكِحُوهُمْ وَلَا يُخَالِطُوهُمْ حَتَّى يُسَلِّمُوا إِلَيْهِمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10547,10547,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ فَرُّوخَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا وَفِيهِ تَقُومُ السَّاعَةُ ‏","","",""],[10548,10548,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الظُّرُوفِ ‏ ‏كُلِّهَا ‏","","",""],[10549,10549,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا سَيِّدُ وَلَدِ ‏ ‏آدَمَ ‏ ‏وَأَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ وَأَوَّلُ شَافِعٍ وَأَوَّلُ مُشَفَّعٍ ‏","","",""],[10550,10550,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَوَّذُوا بِاللَّهِ مِنْ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ وَأَنْ تَظْلِمَ أَوْ تُظْلَمَ ‏","","",""],[10551,10551,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُهِلَّنَّ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏بِفَجِّ الرَّوْحَاءِ ‏ ‏حَاجًّا أَوْ مُعْتَمِرًا ‏","","",""],[10552,10552,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَعِيلُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏كَرِيمَةَ ابْنَةِ الْحَسْحَاسِ الْمُزَنِيَّةِ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏فِي بَيْتِ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا مَعَ عَبْدِي إِذَا هُوَ ذَكَرَنِي وَتَحَرَّكَتْ بِي شَفَتَاهُ ‏","","",""],[10553,10553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏كَرِيمَةَ ابْنَةِ الْحَسْحَاسِ الْمُزَنِيَّةِ ‏ ‏أَنَّهَا حَدَّثَتْهُ قَالَتْ حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَنَحْنُ فِي بَيْتِ هَذِهِ ‏ ‏يَعْنِي ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْثُرُ عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ ‏ ‏أَنَا مَعَ عَبْدِي مَا ذَكَرَنِي وَتَحَرَّكَتْ بِي شَفَتَاهُ ‏","","",""],[10554,10554,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الطُّفَاوَةِ ‏ ‏قَالَ ‏ ‏نَزَلْتُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ وَلَمْ أُدْرِكْ مِنْ صَحَابَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا أَشَدَّ تَشْمِيرًا وَلَا أَقْوَمَ عَلَى ضَيْفٍ مِنْهُ ‏ ‏فَبَيْنَمَا أَنَا عِنْدَهُ وَهُوَ عَلَى سَرِيرٍ لَهُ وَأَسْفَلَ مِنْهُ جَارِيَةٌ لَهُ سَوْدَاءُ وَمَعَهُ كِيسٌ فِيهِ حَصًى وَنَوًى يَقُولُ سُبْحَانَ اللَّهِ سُبْحَانَ اللَّهِ حَتَّى ‏ ‏إِذَا أَنْفَذَ مَا فِي الْكِيسِ أَلْقَاهُ إِلَيْهَا فَجَمَعَتْهُ فَجَعَلَتْهُ فِي الْكِيسِ ثُمَّ دَفَعَتْهُ إِلَيْهِ فَقَالَ لِي أَلَا أُحَدِّثُكَ عَنِّي وَعَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَ فَإِنِّي بَيْنَمَا أَنَا أُوعَكُ فِي ‏ ‏مَسْجِدِ الْمَدِينَةِ ‏ ‏إِذْ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ فَقَالَ ‏ ‏مَنْ أَحَسَّ الْفَتَى ‏ ‏الدَّوْسِيَّ مَنْ أَحَسَّ الْفَتَى ‏ ‏الدَّوْسِيَّ فَقَالَ لَهُ قَائِلٌ هُوَ ذَاكَ يُوعَكُ فِي جَانِبِ الْمَسْجِدِ حَيْثُ ‏ ‏تَرَى يَا رَسُولَ اللَّهِ فَجَاءَ فَوَضَعَ يَدَهُ عَلَيَّ وَقَالَ لِي مَعْرُوفًا فَقُمْتُ فَانْطَلَقَ حَتَّى قَامَ فِي مَقَامِهِ الَّذِي ‏ ‏يُصَلِّي فِيهِ وَمَعَهُ يَوْمَئِذٍ صَفَّانِ مِنْ رِجَالٍ وَصَفٌّ مِنْ نِسَاءٍ ‏ ‏أَوْ صَفَّانِ مِنْ نِسَاءٍ وَصَفٌّ مِنْ رِجَالٍ ‏ ‏فَأَقْبَلَ عَلَيْهِمْ فَقَالَ إِنْ نَسَّانِي الشَّيْطَانُ شَيْئًا مِنْ صَلَاتِي فَلْيُسَبِّحْ الْقَوْمُ وَلْيُصَفِّقْ النِّسَاءُ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَنْسَ مِنْ صَلَاتِهِ شَيْئًا فَلَمَّا سَلَّمَ أَقْبَلَ عَلَيْهِمْ بِوَجْهِهِ فَقَالَ مَجَالِسَكُمْ هَلْ مِنْكُمْ إِذَا أَتَى أَهْلَهُ أَغْلَقَ بَابَهُ وَأَرْخَى سِتْرَهُ ثُمَّ يَخْرُجُ فَيُحَدِّثُ فَيَقُولُ فَعَلْتُ بِأَهْلِي كَذَا وَفَعَلْتُ بِأَهْلِي كَذَا فَسَكَتُوا فَأَقْبَلَ عَلَى النِّسَاءِ فَقَالَ هَلْ مِنْكُنَّ مَنْ تُحَدِّثُ فَجَثَتْ فَتَاةٌ كَعَابٌ عَلَى إِحْدَى رُكْبَتَيْهَا وَتَطَاوَلَتْ ‏ ‏لِيَرَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَسْمَعَ كَلَامَهَا فَقَالَتْ إِي وَاللَّهِ إِنَّهُمْ لَيُحَدِّثُونَ وَإِنَّهُنَّ لَيُحَدِّثْنَ فَقَالَ هَلْ تَدْرُونَ مَا مَثَلُ مَنْ فَعَلَ ذَلِكَ إِنَّ مَثَلَ مَنْ فَعَلَ ذَلِكَ مَثَلُ شَيْطَانٍ وَشَيْطَانَةٍ لَقِيَ أَحَدُهُمَا صَاحِبَهُ بِالسِّكَّةِ قَضَى حَاجَتَهُ مِنْهَا وَالنَّاسُ يَنْظُرُونَ إِلَيْهِ ثُمَّ قَالَ أَلَا لَا يُفْضِيَنَّ رَجُلٌ إِلَى رَجُلٍ وَلَا امْرَأَةٌ إِلَى امْرَأَةٍ إِلَّا إِلَى وَلَدٍ أَوْ وَالِدٍ قَالَ وَذَكَرَ ثَالِثَةً فَنَسِيتُهَا أَلَا إِنَّ طِيبَ الرَّجُلِ مَا وُجِدَ رِيحُهُ وَلَمْ يَظْهَرْ لَوْنُهُ أَلَا إِنَّ طِيبَ النِّسَاءِ مَا ظَهَرَ لَوْنُهُ وَلَمْ يُوجَدْ رِيحُهُ ‏","","",""],[10555,10555,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏شَبِيبٍ أَبِي رَوْحٍ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدِّثْنَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا ‏ ‏إِنَّ الْإِيمَانَ يَمَانٍ وَالْحِكْمَةَ يَمَانِيَةٌ وَأَجِدُ نَفَسَ رَبِّكُمْ مِنْ قِبَلِ ‏ ‏الْيَمَنِ ‏ ‏وَقَالَ ‏ ‏أَبُو الْمُغِيرَةَ ‏ ‏مِنْ قِبَلِ الْمَغْرِبِ ‏ ‏أَلَا إِنَّ الْكُفْرَ وَالْفُسُوقَ وَقَسْوَةَ الْقَلْبِ فِي الْفَدَّادِينَ أَصْحَابِ الشَّعْرِ وَالْوَبَرِ الَّذِينَ يَغْتَالُ الشَّيَاطِينُ عَلَى أَعْجَازِ الْإِبِلِ ‏","","",""],[10556,10556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ أَبُو صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ يَعْنِي ابْنَ أَبِي الْوَضَّاحِ أَبُو سَعِيدٍ الْمُؤَدِّبُ ‏ ‏فِي ذِي الْقَعْدَةِ سَنَةَ سَبْعِينَ فَذَكَرَ حَدِيثًا وَذَكَرَ هَذَا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ إِذَا تَصَدَّقَ بِتَمْرَةٍ مِنْ الطَّيِّبِ وَلَا يَقْبَلُ اللَّهُ إِلَّا الطَّيِّبَ وَقَعَتْ فِي يَدِ اللَّهِ ‏ ‏فَيُرَبِّيهَا لَهُ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى تَعُودَ فِي يَدِهِ مِثْلَ الْجَبَلِ ‏","","",""],[10557,10557,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ أَحَدٌ النَّارَ إِلَّا أُرِيَ مَقْعَدَهُ مِنْ الْجَنَّةِ لَوْ أَحْسَنَ لِيَكُونَ عَلَيْهِ حَسْرَةً وَلَا يَدْخُلُ الْجَنَّةَ أَحَدٌ إِلَّا أُرِيَ مَقْعَدَهُ مِنْ النَّارِ لَوْ أَسَاءَ لِيَزْدَادَ شُكْرًا ‏","","",""],[10558,10558,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ابْنِ مَرْيَمَ ‏ ‏فِي الدُّنْيَا وَالْآخِرَةِ وَالْأَنْبِيَاءُ إِخْوَةٌ أَبْنَاءُ ‏ ‏عَلَّاتٍ ‏ ‏أُمَّهَاتُهُمْ شَتَّى وَلَيْسَ بَيْنَنَا نَبِيٌّ ‏","","",""],[10559,10559,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏هُمْ أَضْعَفُ قُلُوبًا وَأَرَقُّ أَفْئِدَةً الْفِقْهُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ ‏","","",""],[10560,10560,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَحبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْفِقْهُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ ‏","","",""],[10561,10561,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ يَنْقُصُ الْعِلْمُ وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ الْقَتْلُ ‏ ‏هَذَا آخِرُ مُسْنَدِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[10562,10562,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانُوا فِي سَفَرٍ فَمَرُّوا بِحَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏فَاسْتَضَافُوهُمْ فَأَبَوْا أَنْ يُضَيِّفُوهُمْ فَعَرَضَ لِإِنْسَانٍ مِنْهُمْ فِي عَقْلِهِ أَوْ لُدِغَ قَالَ فَقَالُوا ‏ ‏لِأَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ فِيكُمْ مِنْ رَاقٍ فَقَالَ رَجُلٌ مِنْهُمْ نَعَمْ فَأَتَى صَاحِبَهُمْ فَرَقَاهُ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏فَبَرَأَ فَأُعْطِيَ قَطِيعًا مِنْ غَنَمٍ فَأَبَى أَنْ يَقْبَلَ حَتَّى أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا رَقَيْتُهُ إِلَّا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏قَالَ فَضَحِكَ وَقَالَ ‏ ‏مَا يُدْرِيكَ أَنَّهَا رُقْيَةٌ قَالَ ثُمَّ قَالَ خُذُوا وَاضْرِبُوا لِي بِسَهْمٍ مَعَكُمْ ‏","","",""],[10563,10563,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ يَعْنِي ابْنَ زَاذَانَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَحْزِرُ ‏ ‏قِيَامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الظُّهْرِ وَالْعَصْرِ قَالَ ‏ ‏فَحَزَرْنَا ‏ ‏قِيَامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الظُّهْرِ ‏ ‏فِي ‏ ‏الرَّكْعَتَيْنِ الْأُولَيَيْنِ ‏ ‏قَدْرَ ‏ ‏قِرَاءَةِ ثَلَاثِينَ آيَةً ‏ ‏قَدْرَ ‏ ‏قِرَاءَةِ سُورَةِ ‏ ‏تَنْزِيلُ السَّجْدَةِ ‏ ‏قَالَ ‏ ‏وَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الْأُخْرَيَيْنِ عَلَى النِّصْفِ مِنْ ذَلِكَ قَالَ ‏ ‏وَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ عَلَى النِّصْفِ مِنْ ذَلِكَ قَالَ ‏ ‏وَحَزَرْنَا ‏ ‏قِيَامَهُ فِي الْأُخْرَيَيْنِ عَلَى النِّصْفِ مِنْ الْأُولَيَيْنِ ‏","","",""],[10564,10564,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا سَيِّدُ وَلَدِ آدَمَ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ وَأَنَا أَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ وَأَنَا أَوَّلُ شَافِعٍ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ ‏","","",""],[10565,10565,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏مَاعِزُ بْنُ مَالِكٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ أَنَّهُ أَتَى فَاحِشَةً فَرَدَّهُ مِرَارًا قَالَ ثُمَّ أَمَرَ بِهِ فَرُجِمَ قَالَ فَانْطَلَقْنَا فَرَجَمْنَاهُ قَالَ فَانْطَلَقْنَا إِلَى ‏ ‏الْحَرَّةِ ‏ ‏فَرَجَمْنَاهُ ‏ ‏ثُمَّ ‏ ‏وَلَّيْنَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْنَاهُ فَلَمَّا كَانَ مِنْ ‏ ‏الْعَشِيِّ ‏ ‏قَالَ فَحَمِدَ ‏ ‏اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا ‏ ‏بَالُ ‏ ‏أَقْوَامٍ ‏ ‏سَقَطَتْ عَلَى أَبِي كَلِمَةٌ ‏","","",""],[10566,10566,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَتْ بِهِ حَاجَةٌ فَقَالَ لَهُ أَهْلُهُ ائْتِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْأَلْهُ فَأَتَاهُ وَهُوَ يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏مَنْ ‏ ‏اسْتَعَفَّ ‏ ‏أَعَفَّهُ ‏ ‏اللَّهُ وَمَنْ اسْتَغْنَى أَغْنَاهُ اللَّهُ وَمَنْ سَأَلَنَا فَوَجَدْنَا لَهُ أَعْطَيْنَاهُ قَالَ فَذَهَبَ وَلَمْ يَسْأَلْ ‏","","",""],[10567,10567,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي نُعْمٍ الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ مَا يَقْتُلُ الْمُحْرِمُ قَالَ ‏ ‏الْحَيَّةَ وَالْعَقْرَبَ ‏ ‏وَالْفُوَيْسِقَةَ ‏ ‏وَيَرْمِي الْغُرَابَ وَلَا يَقْتُلُهُ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏ ‏وَالْحِدَأَةَ وَالسَّبُعَ ‏ ‏الْعَادِيَ ‏","","",""],[10568,10568,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏أَنْ ‏ ‏يُنْبَذَ ‏ ‏فِيهِ وَعَنْ التَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَعَنْ التَّمْرِ وَالزَّبِيبِ أَنْ يُخْلَطَ بَيْنَهُمَا ‏","","",""],[10569,10569,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ صَاحِبَ التَّمْرِ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَمْرَةٍ فَأَنْكَرَهَا قَالَ ‏ ‏أَنَّى لَكَ هَذَا فَقَالَ اشْتَرَيْنَا ‏ ‏بِصَاعَيْنِ ‏ ‏مِنْ تَمْرِنَا ‏ ‏صَاعًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَيْتُمْ ‏","","",""],[10570,10570,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِّنُوا مَوْتَاكُمْ قَوْلَ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[10571,10571,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللَّهُ بِهِ الْخَطَايَا وَيَزِيدُ بِهِ فِي الْحَسَنَاتِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏ ‏وَكَثْرَةُ ‏ ‏الْخُطَا إِلَى هَذِهِ الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ مَا مِنْكُمْ مِنْ رَجُلٍ يَخْرُجُ مِنْ بَيْتِهِ مُتَطَهِّرًا فَيُصَلِّي مَعَ الْمُسْلِمِينَ الصَّلَاةَ ثُمَّ يَجْلِسُ فِي الْمَجْلِسِ يَنْتَظِرُ الصَّلَاةَ الْأُخْرَى إِنَّ الْمَلَائِكَةَ تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ فَإِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاعْدِلُوا صُفُوفَكُمْ وَأَقِيمُوهَا وَسُدُّوا الْفُرَجَ فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي فَإِذَا قَالَ إِمَامُكُمْ اللَّهُ أَكْبَرُ فَقُولُوا اللَّهُ أَكْبَرُ وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ وَإِنَّ خَيْرَ الصُّفُوفِ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّهَا الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّهَا الْمُقَدَّمُ يَا مَعْشَرَ النِّسَاءِ إِذَا سَجَدَ الرِّجَالُ فَاغْضُضْنَ أَبْصَارَكُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏","","",""],[10572,10572,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ لَتَعْمَلُونَ أَعْمَالًا هِيَ ‏ ‏أَدَقُّ ‏ ‏فِي أَعْيُنِكُمْ مِنْ الشَّعْرِ كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمُوبِقَاتِ ‏","","",""],[10573,10573,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏رُبَيْحُ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْنَا يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ مِنْ شَيْءٍ نَقُولُهُ فَقَدْ ‏ ‏بَلَغَتْ ‏ ‏الْقُلُوبُ الْحَنَاجِرَ قَالَ نَعَمْ ‏ ‏اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا وَآمِنْ رَوْعَاتِنَا ‏ ‏قَالَ ‏ ‏فَضَرَبَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ وُجُوهَ أَعْدَائِهِ بِالرِّيحِ فَهَزَمَهُمْ اللَّهُ عَزَّ وَجَلَّ بِالرِّيحِ ‏","","",""],[10574,10574,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ حَسَنٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرِو بْنِ سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا مِنَّا قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏نَسِيتُ اسْمَهُ وَلَكِنْ اسْمُهُ ‏ ‏مُعَاوِيَةُ ‏ ‏أَوْ ‏ ‏ابْنُ مُعَاوِيَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ يَعْرِفُ مَنْ يَحْمِلُهُ وَمَنْ يُغَسِّلُهُ وَمَنْ ‏ ‏يُدَلِّيهِ فِي قَبْرِهِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَهُوَ فِي الْمَجْلِسِ ‏ ‏مِمَّنْ سَمِعْتَ هَذَا قَالَ مِنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَانْطَلَقَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏مِمَّنْ سَمِعْتَ هَذَا قَالَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10575,10575,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَمَرَنَا نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَقْرَأَ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَمَا تَيَسَّرَ ‏","","",""],[10576,10576,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ مَرْدَانُبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَسَنُ ‏ ‏وَالْحُسَيْنُ ‏ ‏سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ ‏","","",""],[10577,10577,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِنَازَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏إِنَّ هَذِهِ الْأُمَّةَ ‏ ‏تُبْتَلَى ‏ ‏فِي قُبُورِهَا فَإِذَا الْإِنْسَانُ دُفِنَ فَتَفَرَّقَ عَنْهُ أَصْحَابُهُ جَاءَهُ مَلَكٌ فِي يَدِهِ مِطْرَاقٌ فَأَقْعَدَهُ قَالَ مَا تَقُولُ فِي هَذَا الرَّجُلِ فَإِنْ كَانَ مُؤْمِنًا قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فَيَقُولُ ‏ ‏صَدَقْتَ ثُمَّ يُفْتَحُ لَهُ بَابٌ إِلَى النَّارِ فَيَقُولُ هَذَا كَانَ مَنْزِلُكَ لَوْ كَفَرْتَ بِرَبِّكَ فَأَمَّا إِذْ آمَنْتَ فَهَذَا مَنْزِلُكَ فَيُفْتَحُ لَهُ بَابٌ إِلَى الْجَنَّةِ فَيُرِيدُ أَنْ يَنْهَضَ إِلَيْهِ فَيَقُولُ لَهُ اسْكُنْ وَيُفْسَحُ لَهُ فِي قَبْرِهِ وَإِنْ كَانَ كَافِرًا ‏ ‏أَوْ مُنَافِقًا ‏ ‏يَقُولُ لَهُ مَا تَقُولُ فِي هَذَا الرَّجُلِ فَيَقُولَ لَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَيَقُولُ لَا دَرَيْتَ وَلَا ‏ ‏تَلَيْتَ ‏ ‏وَلَا اهْتَدَيْتَ ثُمَّ يُفْتَحُ لَهُ بَابٌ إِلَى الْجَنَّةِ فَيَقُولُ هَذَا مَنْزِلُكَ لَوْ آمَنْتَ بِرَبِّكَ فَأَمَّا إِذْ كَفَرْتَ بِهِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ أَبْدَلَكَ بِهِ هَذَا وَيُفْتَحُ لَهُ بَابٌ إِلَى النَّارِ ثُمَّ ‏ ‏يَقْمَعُهُ ‏ ‏قَمْعَةً ‏ ‏بِالْمِطْرَاقِ يَسْمَعُهَا خَلْقُ اللَّهِ كُلُّهُمْ غَيْرَ ‏ ‏الثَّقَلَيْنِ ‏ ‏فَقَالَ بَعْضُ الْقَوْمِ يَا رَسُولَ اللَّهِ مَا أَحَدٌ يَقُومُ عَلَيْهِ مَلَكٌ فِي يَدِهِ مِطْرَاقٌ إِلَّا ‏ ‏هُبِلَ ‏ ‏عِنْدَ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ ‏}","","",""],[10578,10578,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَتْرُ ‏ ‏بِلَيْلٍ ‏","","",""],[10579,10579,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَ ‏ ‏ابْنَ صَائِدٍ ‏ ‏عَنْ تُرْبَةِ الْجَنَّةِ فَقَالَ ‏ ‏دَرْمَكَةٌ ‏ ‏بَيْضَاءُ مِسْكٌ خَالِصٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏","","",""],[10580,10580,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏حَفْصَ بْنَ عَاصِمٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏","","",""],[10581,10581,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ لَقَدْ سَمِعْتُ فُلَانًا وَفُلَانًا يُحْسِنَانِ الثَّنَاءَ يَذْكُرَانِ أَنَّكَ أَعْطَيْتَهُمَا دِينَارَيْنِ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكِنَّ وَاللَّهِ فُلَانًا مَا هُوَ كَذَلِكَ لَقَدْ أَعْطَيْتُهُ مِنْ عَشَرَةٍ إِلَى مِائَةٍ فَمَا يَقُولُ ذَاكَ أَمَا وَاللَّهِ ‏ ‏إِنَّ أَحَدَكُمْ لَيُخْرِجُ مَسْأَلَتَهُ مِنْ عِنْدِي يَتَأَبَّطُهَا ‏ ‏يَعْنِي تَكُونُ تَحْتَ إِبْطِهِ ‏ ‏يَعْنِي نَارًا قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ لِمَ ‏ ‏تُعْطِيهَا إِيَّاهُمْ قَالَ فَمَا أَصْنَعُ يَأْبَوْنَ إِلَّا ذَاكَ ‏ ‏وَيَأْبَى اللَّهُ لِي الْبُخْلَ ‏","","",""],[10582,10582,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏مَوْلَى ‏ ‏ابْنِ سِبَاعٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَغَنَّى أَغْنَاهُ اللَّهُ وَمَنْ ‏ ‏تَعَفَّفَ ‏ ‏أَعَفَّهُ ‏ ‏اللَّهُ ‏","","",""],[10583,10583,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ ‏ ‏وَالْوَرِقَ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا مِثْلًا بِمِثْلٍ وَلَا ‏ ‏تُشِفُّوا ‏ ‏بَعْضَهَا عَلَى بَعْضٍ وَلَا تَبِيعُوا شَيْئًا غَائِبًا مِنْهَا ‏ ‏بِنَاجِزٍ ‏ ‏فَإِنِّي أَخَافُ عَلَيْكُمْ الرَّمَاءَ وَالرَّمَاءُ الرِّبَا ‏ ‏قَالَ ‏ ‏فَحَدَّثَ رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏يُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا تَمَّ مَقَالَتَهُ حَتَّى دَخَلَ بِهِ عَلَى ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَأَنَا مَعَهُ فَقَالَ إِنَّ هَذَا حَدَّثَنِي عَنْكَ حَدِيثًا يَزْعُمُ أَنَّكَ تُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَسَمِعْتَهُ فَقَالَ بَصُرَ عَيْنِي وَسَمِعَ أُذُنِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ وَلَا ‏ ‏الْوَرِقَ ‏ ‏بِالْوَرِقِ ‏ ‏إِلَّا مِثْلًا ‏ ‏بِمِثْلٍ ‏ ‏وَلَا ‏ ‏تُشِفُّوا ‏ ‏بَعْضَهَا عَلَى بَعْضٍ وَلَا تَبِيعُوا شَيْئًا ‏ ‏غَائِبًا ‏ ‏مِنْهَا ‏ ‏بِنَاجِزٍ ‏","","",""],[10584,10584,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يُصِيبُهُ ‏ ‏وَصَبٌ ‏ ‏وَلَا ‏ ‏نَصَبٌ ‏ ‏وَلَا حَزَنٌ وَلَا ‏ ‏سَقَمٌ ‏ ‏وَلَا ‏ ‏أَذًى ‏ ‏حَتَّى الْهَمُّ يُهِمُّهُ إِلَّا يُكَفِّرُ اللَّهُ عَنْهُ مِنْ سَيِّئَاتِهِ ‏","","",""],[10585,10585,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ ‏ ‏عَلِيٌّ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَهَبَةٍ فِي ‏ ‏أَدِيمٍ ‏ ‏مَقْرُوظٍ ‏ ‏لَمْ تُحَصَّلْ مِنْ تُرَابِهَا فَقَسَمَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَرْبَعَةٍ بَيْنَ ‏ ‏زَيْدِ الْخَيْرِ ‏ ‏وَالْأَقْرَعِ بْنِ حَابِسٍ ‏ ‏وَعُيَيْنَةَ بْنِ حِصْنٍ ‏ ‏وَعَلْقَمَةَ بْنِ عُلَاثَةَ ‏ ‏أَوْ ‏ ‏عَامِرِ بْنِ الطُّفَيْلِ ‏ ‏شَكَّ ‏ ‏عُمَارَةُ ‏ ‏فَوَجَدَ مِنْ ذَلِكَ بَعْضُ أَصْحَابِهِ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَغَيْرُهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَأْتَمِنُونِي وَأَنَا أَمِينُ مَنْ فِي السَّمَاءِ يَأْتِينِي خَبَرٌ مِنْ السَّمَاءِ صَبَاحًا وَمَسَاءً ثُمَّ أَتَاهُ رَجُلٌ ‏ ‏غَائِرُ ‏ ‏الْعَيْنَيْنِ ‏ ‏مُشْرِفُ ‏ ‏الْوَجْنَتَيْنِ ‏ ‏نَاشِزُ ‏ ‏الْجَبْهَةِ ‏ ‏كَثُّ ‏ ‏اللِّحْيَةِ مُشَمَّرُ ‏ ‏الْإِزَارِ ‏ ‏مَحْلُوقُ الرَّأْسِ فَقَالَ اتَّقِ اللَّهِ يَا رَسُولَ اللَّهِ قَالَ فَرَفَعَ رَأْسَهُ إِلَيْهِ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏أَلَسْتُ أَحَقَّ أَهْلِ الْأَرْضِ أَنْ يَتَّقِيَ اللَّهَ أَنَا ثُمَّ ‏ ‏أَدْبَرَ ‏ ‏فَقَالَ ‏ ‏خَالِدٌ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا أَضْرِبُ عُنُقَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَعَلَّهُ يَكُونُ ‏ ‏يُصَلِّي فَقَالَ إِنَّهُ ‏ ‏رُبَّ ‏ ‏مُصَلٍّ يَقُولُ بِلِسَانِهِ مَا لَيْسَ فِي قَلْبِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَمْ أُومَرْ أَنْ ‏ ‏أُنَقِّبَ ‏ ‏عَنْ قُلُوبِ النَّاسِ وَلَا أَشُقَّ بُطُونَهُمْ ثُمَّ نَظَرَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُقَفٍّ ‏ ‏فَقَالَ هَا ‏ ‏إِنَّهُ سَيَخْرُجُ ‏ ‏مِنْ ‏ ‏ضِئْضِئِ ‏ ‏هَذَا قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ ‏ ‏مِنْ ‏ ‏الرَّمِيَّةِ ‏","","",""],[10586,10586,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏ضِرَارٌ يَعْنِي ابْنَ مُرَّةَ أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏إِنَّ الصَّوْمَ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ إِنَّ لِلصَّائِمِ فَرْحَتَيْنِ إِذَا أَفْطَرَ فَرِحَ وَإِذَا لَقِيَ اللَّهَ فَجَزَاهُ فَرِحَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[10587,10587,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ ‏ ‏سُئِلَ عَنْ ‏ ‏الْإِزَارِ ‏ ‏فَقَالَ عَلَى ‏ ‏الْخَبِيرِ ‏ ‏سَقَطْتَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِزْرَةُ ‏ ‏الْمُؤْمِنِ إِلَى أَنْصَافِ السَّاقَيْنِ لَا ‏ ‏جُنَاحَ ‏ ‏أَوْ لَا حَرَجَ ‏ ‏عَلَيْهِ فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ مَا كَانَ أَسْفَلَ مِنْ ذَلِكَ فَهُوَ فِي النَّارِ لَا يَنْظُرُ اللَّهُ إِلَى مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[10588,10588,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبِنَاءِ الْمَسْجِدِ فَجَعَلْنَا نَنْقُلُ ‏ ‏لَبِنَةً ‏ ‏لَبِنَةً ‏ ‏وَكَانَ ‏ ‏عَمَّارٌ ‏ ‏يَنْقُلُ ‏ ‏لَبِنَتَيْنِ ‏ ‏لَبِنَتَيْنِ ‏ ‏فَتَتَرَّبُ رَأْسُهُ قَالَ فَحَدَّثَنِي أَصْحَابِي وَلَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ جَعَلَ يَنْفُضُ رَأْسَهُ وَيَقُولُ ‏ ‏وَيْحَكَ ‏ ‏يَا ‏ ‏ابْنَ سُمَيَّةَ ‏ ‏تَقْتُلُكَ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏","","",""],[10589,10589,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ فِي آخِرِ الزَّمَانِ خَلِيفَةٌ يُعْطِي الْمَالَ وَلَا يَعُدُّهُ عَدًّا ‏","","",""],[10590,10590,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ ‏ ‏مَضَبَّةٍ ‏ ‏فَمَا تَأْمُرُنَا ‏ ‏أَوْ مَا ‏ ‏تُفْتِينَا ‏ ‏قَالَ ذُكِرَ لِي أَنَّ أُمَّةً مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُسِخَتْ ‏ ‏فَلَمْ يَأْمُرْ وَلَمْ يَنْهَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَلَمَّا كَانَ بَعْدَ ذَلِكَ قَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ اللَّهَ لَيَنْفَعُ بِهِ غَيْرَ وَاحِدٍ وَإِنَّهُ لَطَعَامُ عَامَّةِ الرِّعَاءِ وَلَوْ كَانَ عِنْدِي لَطَعِمْتُهُ ‏ ‏وَإِنَّمَا عَافَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[10591,10591,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَصْرُخُ بِالْحَجِّ صُرَاخًا حَتَّى إِذَا طُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏قَالَ ‏ ‏اجْعَلُوهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏قَالَ فَجَعَلْنَاهَا عُمْرَةً فَحَلَلْنَا فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏صَرَخْنَا بِالْحَجِّ وَانْطَلَقْنَا إِلَى ‏ ‏مِنًى ‏","","",""],[10592,10592,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏انْتَظَرْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً صَلَاةَ الْعِشَاءِ حَتَّى ذَهَبَ نَحْوٌ مِنْ ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ قَالَ فَجَاءَ فَصَلَّى بِنَا ثُمَّ قَالَ ‏ ‏خُذُوا مَقَاعِدَكُمْ فَإِنَّ النَّاسَ قَدْ أَخَذُوا مَضَاجِعَهُمْ وَإِنَّكُمْ لَنْ تَزَالُوا فِي صَلَاةٍ مُنْذُ انْتَظَرْتُمُوهَا وَلَوْلَا ضَعْفُ الضَّعِيفِ ‏ ‏وَسَقَمُ ‏ ‏السَّقِيمِ ‏ ‏وَحَاجَةُ ذِي ‏ ‏الْحَاجَةِ ‏ ‏لَأَخَّرْتُ هَذِهِ الصَّلَاةَ إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ ‏","","",""],[10593,10593,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا لَا يَمُوتُونَ وَلَا يَحْيَوْنَ وَأَمَّا أُنَاسٌ يُرِيدُ اللَّهُ بِهِمْ الرَّحْمَةَ فَيُمِيتُهُمْ فِي النَّارِ فَيَدْخُلُ عَلَيْهِمْ الشُّفَعَاءُ فَيَأْخُذُ الرَّجُلُ أَنْصَارَهُ فَيَبُثُّهُمْ ‏ ‏أَوْ قَالَ فَيَنْبُتُونَ ‏ ‏عَلَى نَهَرِ الْحَيَاءِ ‏ ‏أَوْ قَالَ الْحَيَوَانِ أَوْ قَالَ الْحَيَاةِ أَوْ قَالَ نَهَرِ الْجَنَّةِ ‏ ‏فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا تَرَوْنَ الشَّجَرَةَ تَكُونُ خَضْرَاءَ ثُمَّ تَكُونُ صَفْرَاءَ ‏ ‏أَوْ قَالَ تَكُونُ صَفْرَاءَ ثُمَّ تَكُونُ خَضْرَاءَ ‏ ‏قَالَ فَقَالَ بَعْضُهُمْ كَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ بِالْبَادِيَةِ ‏","","",""],[10594,10594,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ ‏ ‏هَيْبَةُ ‏ ‏النَّاسِ أَنْ يَقُولَ فِي حَقٍّ إِذَا رَآهُ أَوْ شَهِدَهُ أَوْ سَمِعَهُ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَدِدْتُ أَنِّي لَمْ أَسْمَعْهُ ‏","","",""],[10595,10595,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ قَوْمًا يَكُونُونَ فِي أُمَّتِهِ يَخْرُجُونَ فِي فِرْقَةٍ مِنْ النَّاسِ ‏ ‏سِيمَاهُمْ ‏ ‏التَّحْلِيقُ ‏ ‏هُمْ شَرُّ الْخَلْقِ ‏ ‏أَوْ مِنْ شَرِّ الْخَلْقِ ‏ ‏يَقْتُلُهُمْ ‏ ‏أَدْنَى ‏ ‏الطَّائِفَتَيْنِ ‏ ‏مِنْ الْحَقِّ قَالَ فَضَرَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُمْ مَثَلًا ‏ ‏أَوْ قَالَ قَوْلًا ‏ ‏الرَّجُلُ يَرْمِي ‏ ‏الرَّمِيَّةَ ‏ ‏أَوْ قَالَ الْغَرَضَ ‏ ‏فَيَنْظُرُ فِي ‏ ‏النَّصْلِ ‏ ‏فَلَا يَرَى بَصِيرَةً وَيَنْظُرُ فِي ‏ ‏النَّضِيِّ ‏ ‏فَلَا يَرَى بَصِيرَةً وَيَنْظُرُ فِي ‏ ‏الْفُوقِ ‏ ‏فَلَا يَرَى بَصِيرَةً ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَأَنْتُمْ قَتَلْتُمُوهُمْ يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏","","",""],[10596,10596,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِأَصْحَابِهِ ثُمَّ جَاءَ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يَتَّجِرُ ‏ ‏عَلَى هَذَا ‏ ‏أَوْ يَتَصَدَّقُ عَلَى هَذَا ‏ ‏فَيُصَلِّيَ مَعَهُ قَالَ فَصَلَّى مَعَهُ رَجُلٌ ‏","","",""],[10597,10597,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعْتُمْ النِّدَاءَ فَقُولُوا كَمَا يَقُولُ الْمُؤَذِّنُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏عَبْدُ اللَّهِ بْنُ عَوْنٍ الْخَرَّازُ ‏ ‏وَمُصْعَبٌ الزُّبَيْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فَذَكَرَ مِثْلَهُ سَوَاءً ‏","","",""],[10598,10598,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةُ ‏ ‏اشْتِرَاءُ الثَّمَرَةِ فِي رُءُوسِ النَّخْلِ بِالتَّمْرِ كَيْلًا ‏ ‏وَالْمُحَاقَلَةُ ‏ ‏كَرْيُ ‏ ‏الْأَرْضِ ‏","","",""],[10599,10599,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لِبْسَتَيْنِ وَعَنْ بَيْعَتَيْنِ أَمَّا الْبَيْعَتَانِ ‏ ‏الْمُلَامَسَةُ ‏ ‏وَالْمُنَابَذَةُ ‏ ‏وَاللِّبْسَتَانِ ‏ ‏اشْتِمَالُ ‏ ‏الصَّمَّاءِ ‏ ‏وَالِاحْتِبَاءُ ‏ ‏فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ ‏","","",""],[10600,10600,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏اشْتِمَالِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏و حَدَّثَنَاه ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏يَعْنِي مِثْلَ الْحَدِيثِ ‏","","",""]];
